/**
 * TEMPORARY, THROWAWAY DEMO — not intended to merge. See the PR this ships on for context: it
 * exists purely to show the shared ZimmProductCard component family (PR #85) live, against real
 * SFCC product data, from the homepage, via this repo's ephemeral MRT preview environment.
 *
 * Grouped by SFCC-236 AC category (Core component / PLP / Home / Wishlist / Recently Viewed),
 * one card per genuinely distinct required variant/state — sourced from a direct cross-reference
 * of the live Jira ACs + comment thread, the real Figma component variants, and every state
 * already exercised anywhere in this component family's own Storybook coverage (2026-09-05).
 * Confirmed NOT separate states, so deliberately not built as extra cards: the three
 * viewport-gated behaviours (PLP mobile bag-hide, PLP mobile notify-me swap, Home mobile
 * always-visible price — each group's own on-page note says which cards to resize the browser
 * against), and the real :hover/:has(:focus-visible) reveal (provable live on any interactive
 * card here — an advantage over Storybook, which can't force a real hover). Confirmed NOT
 * applicable to this demo at all: a Hero variant (orphaned Figma node, no owning ticket, no 4th
 * `variation` value exists), a Tablet-specific design (no such Figma variant exists), Recently
 * Viewed's separate *carousel* surface (SFCC-83, a different component with no code path today —
 * not to be confused with the Full History grid shown here), and three Wishlist CRM-backed
 * requirements (a distinct "What's Now" price type, a region-unavailable state, a destructive
 * add-to-bag treatment) that are PRD-confirmed but never built into the shipped component.
 *
 * Every card reuses ONE real fetched product's data as a shared base, overriding only the
 * specific prop(s) each state needs — the same `{...Default.args, <override>}` pattern
 * organisms/zimmProductCard/index.stories.tsx's own stories already use, just with a real
 * product substituted for its hand-authored SVG fixture. Add-to-bag is fully real (the same
 * `addItemToNewOrExistingBasket` mutation the PDP uses); `onNotifyMe`/`onRemove` are demo-only
 * toasts, since no such mutation exists anywhere in this codebase to wire them to for real.
 *
 * Known, un-fixed gap: `ZimmProductCardContent`'s bag button has no loading-spinner slot at all
 * (only `isUnavailable` exists as a lever) — a slow add-to-bag request shows no in-button pending
 * state. Not fixed here; that would be scope creep onto a broadly-consumed shared component for a
 * throwaway demo page.
 */
import React, { useMemo, useState } from 'react';
import { useIntl } from 'react-intl';
import { Box, Flex, SimpleGrid, Text } from '@salesforce/retail-react-app/app/components/shared/ui';
import Section from '@salesforce/retail-react-app/app/components/section';
import {
  useProductSearch,
  useShopperBasketsV2MutationHelper as useShopperBasketsMutationHelper,
} from '@salesforce/commerce-sdk-react';
import { useToast } from '@salesforce/retail-react-app/app/hooks/use-toast';
import { HOME_SHOP_PRODUCTS_LIMIT } from '../../constants';
import { ZimmProductCard } from '../../components/ui-kits/organisms/zimmProductCard';
import type { ZimmProductCardProps } from '../../components/ui-kits/organisms/zimmProductCard';
import {
  pickDemoHit,
  selectLiveProductCardBase,
  buildSizeChipValues,
  type LiveDemoSourceHit,
} from './liveProductCardDemoMapper';

/**
 * Page-local, unexported adaptation of organisms/zimmProductCard/index.stories.tsx's own
 * `LiveSizeSelectionCard` — same narrowing reasoning that file documents: attaching
 * `selectedSizeChipValue`/`onSizeChipSelect` onto an *unnarrowed* prop spread fails `tsc` on the
 * `home` union branch, so narrow via the `variation` discriminant first.
 */
const DemoSizeSelectableCard = (props: ZimmProductCardProps) => {
  const [selectedSizeChipValue, setSelectedSizeChipValue] = useState<string | undefined>(() =>
    props.variation === 'plp' || props.variation === 'wishlist' ? props.selectedSizeChipValue : undefined,
  );
  const isSizeChipVariation = props.variation === 'plp' || props.variation === 'wishlist';
  const onSizeChipSelectFromProps = isSizeChipVariation ? props.onSizeChipSelect : undefined;
  const handleSizeChipSelect = (value: string) => {
    setSelectedSizeChipValue(value);
    onSizeChipSelectFromProps?.(value);
  };
  const propsWithLiveSelection: ZimmProductCardProps = isSizeChipVariation
    ? { ...props, selectedSizeChipValue, onSizeChipSelect: handleSizeChipSelect }
    : props;
  return <ZimmProductCard {...propsWithLiveSelection} />;
};

export const LiveProductCardDemoSection = () => {
  const intl = useIntl();
  const showToast = useToast();
  const { addItemToNewOrExistingBasket } = useShopperBasketsMutationHelper();

  const {
    data: productSearchResult,
    isLoading: isSearchLoading,
    isError: isSearchError,
    error: searchError,
  } = useProductSearch({
    parameters: {
      // Confirmed live (2026-09-05): HOME_SHOP_PRODUCTS_CATEGORY_ID ('newarrivals') is a generic
      // base-template sample category with zero real hits in Zimmermann's actual catalog -- the
      // existing "Shop Products" section elsewhere on this page has this exact same latent gap.
      // A free-text query is independent of category taxonomy entirely, so it doesn't matter that
      // the real category structure is unknown/undocumented -- confirmed more robust for a
      // throwaway demo than guessing at a real cgid.
      q: 'dress',
      // `htype` is a `refine` VALUE, not its own top-level param -- confirmed against
      // commerce-sdk-isomorphic's real ProductSearchParams, which has no `htype` field at all.
      // A bogus top-level `htype` key silently type-checks (the SDK's params type intersects
      // with a permissive QueryParameters) but does nothing at runtime, so this was searching
      // unscoped by hit type.
      refine: 'htype=master',
      expand: ['promotions', 'variations', 'prices', 'images', 'custom_properties'],
      // Per the SDK's own doc comment: if `allImages` isn't passed at all, `imageGroups` is
      // omitted from the response outright, regardless of `expand` including 'images' -- this,
      // not the viewType filter, was the real reason cards rendered with no image.
      allImages: true,
      perPricebook: true,
      allVariationProperties: true,
      limit: HOME_SHOP_PRODUCTS_LIMIT,
    },
  });

  const formatPrice = (amount: number, currency: string) => intl.formatNumber(amount, { style: 'currency', currency });

  const demoHit = useMemo(
    () => pickDemoHit((productSearchResult?.hits ?? []) as LiveDemoSourceHit[]),
    [productSearchResult],
  );
  const demoProduct = useMemo(() => (demoHit ? selectLiveProductCardBase(demoHit, formatPrice) : null), [demoHit]);
  const sizeChipValues = useMemo(() => (demoHit ? buildSizeChipValues(demoHit) : []), [demoHit]);

  const handleAddToBagAsync = async () => {
    if (!demoProduct) return;
    try {
      await addItemToNewOrExistingBasket([
        { productId: demoProduct.variantProductId, price: demoProduct.variantPrice, quantity: 1 },
      ]);
      showToast({ title: 'Added to bag', status: 'success' });
    } catch (error) {
      showToast({
        title: error instanceof Error ? error.message : 'Could not add to bag',
        status: 'error',
      });
    }
  };
  // ZimmProductCard's onAddToBag is () => void -- wrap the async handler so we never hand a
  // Promise-returning function to a void-expecting prop (the try/catch above already handles
  // rejection, so there's nothing left for a caller to await or catch here).
  const handleAddToBag = () => {
    void handleAddToBagAsync();
  };
  const demoNotifyMe = () => showToast({ title: 'Notify me (demo only)', status: 'info' });
  const demoRemove = () => showToast({ title: 'Removed from wishlist (demo only)', status: 'info' });

  // TEMPORARY diagnostic, throwaway-demo only: render the actual reason nothing shows, instead of
  // silently returning null on any of loading/error/empty-hits/unusable-hit.
  if (isSearchLoading) {
    return (
      <Section padding={4} paddingTop={16} title="Live Product Card Demo (Temporary)">
        <Text>Loading live product data…</Text>
      </Section>
    );
  }
  if (isSearchError) {
    return (
      <Section padding={4} paddingTop={16} title="Live Product Card Demo (Temporary)">
        <Text color="red.500">
          Product search failed: {searchError instanceof Error ? searchError.message : String(searchError)}
        </Text>
      </Section>
    );
  }
  if (!productSearchResult?.hits?.length) {
    return (
      <Section padding={4} paddingTop={16} title="Live Product Card Demo (Temporary)">
        <Text color="orange.500">Product search returned zero hits for this category/refinement.</Text>
      </Section>
    );
  }
  if (!demoProduct) {
    return (
      <Section padding={4} paddingTop={16} title="Live Product Card Demo (Temporary)">
        <Text color="orange.500">
          Got {productSearchResult.hits.length} hit(s), but none had a usable productName to build a card from.
        </Text>
      </Section>
    );
  }

  const { base, colour, size } = demoProduct;
  const hasMultipleImages = Boolean(base.images && base.images.length > 1);

  const plpBase: ZimmProductCardProps = {
    ...base,
    id: 'live-demo-plp',
    variation: 'plp',
    badge: 'Runway',
    onAddToBag: handleAddToBag,
    sizeChipValues,
    onSizeChipSelect: () => {},
  };
  const wishlistBase: ZimmProductCardProps = {
    ...base,
    id: 'live-demo-wishlist',
    variation: 'wishlist',
    badge: 'Runway',
    colour: colour ?? 'Colour',
    size: size ?? 'Size',
    onRemove: demoRemove,
    onAddToBag: handleAddToBag,
    sizeChipValues,
    onSizeChipSelect: () => {},
  };
  const homeBase: ZimmProductCardProps = {
    ...base,
    id: 'live-demo-home',
    variation: 'home',
    badge: 'Runway',
  };

  const oneSizeChipValues = [{ value: 'os', label: 'One size' }];

  type DemoCard = { label: string; card: ZimmProductCardProps; interactive: boolean };
  type DemoGroup = { category: string; note?: string; cards: DemoCard[] };

  // Grouping and every card below is sourced from a single research pass cross-referencing the
  // live SFCC-236 ACs, the real Figma component variants, and every state already exercised
  // anywhere in this component family's own Storybook coverage (2026-09-05) -- see this file's
  // own docblock for the full audit summary.
  const groups: DemoGroup[] = [
    {
      category: 'Core Component',
      note:
        'Variation-agnostic behaviours (AC1 + the Image Group/Price Figma nodes) -- shown once, ' +
        'not repeated per variation below. Hover over any interactive card on this page (or Tab ' +
        'to focus it) to see the live price↔size-chip reveal, arrow controls, and stretched-link ' +
        '-- real CSS :hover/:has(:focus-visible), not a separate card to build.',
      cards: [
        {
          label: 'Single Image',
          card: { ...plpBase, id: 'live-demo-single', hoverImage: undefined, images: undefined },
          interactive: true,
        },
        {
          label: 'Hover-Swap Pair',
          card: { ...plpBase, id: 'live-demo-hover-swap', images: undefined },
          interactive: true,
        },
        {
          label: 'Multiple Images',
          card: hasMultipleImages
            ? { ...plpBase, id: 'live-demo-multi', hoverImage: undefined }
            : { ...plpBase, id: 'live-demo-multi' },
          interactive: true,
        },
        {
          label: 'Sale Price',
          card: {
            ...plpBase,
            id: 'live-demo-sale',
            originalPrice:
              typeof demoProduct.variantPrice === 'number'
                ? formatPrice(demoProduct.variantPrice * 1.4, demoHit?.currency ?? 'USD')
                : undefined,
          },
          interactive: true,
        },
        {
          label: 'Loading Price',
          card: { ...plpBase, id: 'live-demo-loading', currentPrice: undefined, isPriceLoading: true },
          interactive: true,
        },
      ],
    },
    {
      category: 'PLP',
      note:
        'Resize the browser below 768px to check the mobile-only bag-hide (Default) and ' +
        'price/bag→Notify Me swap (Out of Stock) on these same two cards -- both are ' +
        'viewport-gated, not separate states.',
      cards: [
        { label: 'Default', card: plpBase, interactive: true },
        {
          label: 'Out of Stock',
          card: { ...plpBase, id: 'live-demo-plp-oos', isUnavailable: true, onNotifyMe: demoNotifyMe },
          interactive: true,
        },
        {
          label: 'One Size',
          card: { ...plpBase, id: 'live-demo-plp-onesize', sizeChipValues: oneSizeChipValues },
          interactive: false,
        },
      ],
    },
    {
      category: 'Home',
      note:
        "Badge and hover-swap image are deliberately passed to both cards below -- Home's own " +
        'VARIATION_CONFIG suppresses both regardless (Jira comment 13880), which is what these ' +
        "prove, not just omit. Out of Stock's price/notify-me is additive on hover here, unlike " +
        "PLP/Wishlist's swap. Resize below 768px to check the mobile-only always-visible price.",
      cards: [
        { label: 'Default', card: homeBase, interactive: false },
        {
          label: 'Out of Stock',
          card: { ...homeBase, id: 'live-demo-home-oos', isUnavailable: true, onNotifyMe: demoNotifyMe },
          interactive: false,
        },
      ],
    },
    {
      category: 'Wishlist',
      note:
        'The hover-revealed size-chip picker here matches PLP by design/Figma; the written AC ' +
        'text for Wishlist calls out only image-swap + arrows on hover -- an already-accepted ' +
        'design-over-AC-text call, not a bug in this demo.',
      cards: [
        { label: 'Default', card: wishlistBase, interactive: true },
        {
          label: 'Out of Stock',
          card: { ...wishlistBase, id: 'live-demo-wishlist-oos', isUnavailable: true, onNotifyMe: demoNotifyMe },
          interactive: true,
        },
        {
          label: 'One Size',
          card: {
            ...wishlistBase,
            id: 'live-demo-wishlist-onesize',
            size: 'One size',
            sizeChipValues: oneSizeChipValues,
          },
          interactive: false,
        },
      ],
    },
    {
      category: 'Recently Viewed (Full History)',
      note:
        "Not a distinct variation -- confirmed identical to PLP (variation: 'plp', organism " +
        'docblock). Shown as its own labelled section purely so this AC category is directly ' +
        'checkable, not because different props exist to demonstrate.',
      cards: Array.from({ length: 4 }, (_, index) => ({
        label: `Recently Viewed ${index + 1}`,
        card: { ...plpBase, id: `live-demo-recently-viewed-${index + 1}` },
        interactive: true,
      })),
    },
  ];

  const totalCards = groups.reduce((sum, group) => sum + group.cards.length, 0);

  return (
    <Box as="section" paddingY="var(--zimm-scale-4xl)">
      {/* Header bar modeled on the "Recently Viewed" PLP-bar pattern (Figma node 3332-35655's
          "Recently Viewed Container") -- uppercase heading + right-aligned item count, same row. */}
      <Flex
        justify="space-between"
        align="baseline"
        paddingX="var(--zimm-scale-3xl)"
        marginBottom="var(--zimm-scale-2xl)"
      >
        <Text textStyle="heading3" textTransform="uppercase">
          Live Product Card Demo (Temporary)
        </Text>
        <Text textStyle="label">{totalCards} ITEMS</Text>
      </Flex>
      {groups.map((group, groupIndex) => (
        <Box
          key={group.category}
          marginBottom="var(--zimm-scale-4xl)"
          paddingBottom={groupIndex < groups.length - 1 ? 'var(--zimm-scale-3xl)' : undefined}
          borderBottom={
            groupIndex < groups.length - 1
              ? 'var(--zimm-border-width-default) solid var(--zimm-color-border-default)'
              : undefined
          }
        >
          <Box paddingX="var(--zimm-scale-3xl)" marginBottom="var(--zimm-scale-xs)">
            <Text textStyle="productNames" textTransform="uppercase">
              {group.category}
            </Text>
            {group.note && (
              <Text
                textStyle="caption"
                color="var(--zimm-color-text-muted)"
                maxWidth="640px"
                marginTop="var(--zimm-scale-2xs)"
              >
                {group.note}
              </Text>
            )}
          </Box>
          {/* Grid modeled on the "Recently Viewed" full-history grid (Figma nodes 3332-35664 /
              3332-35665) -- full-bleed to the viewport edge (no side gutters), generous
              --zimm-scale-4xl gap on both axes, responsive 4/3/2 columns per breakpoint. */}
          <SimpleGrid
            columns={{ base: 2, md: 3, lg: 4 }}
            gap="var(--zimm-scale-4xl)"
            justifyItems="center"
            marginTop="var(--zimm-scale-2xl)"
            // Standard "break out of a padded container" technique -- this page's ambient content
            // wrapper (outside this component, above Home in the app shell -- the nav/logo render
            // outside it and aren't affected) insets page body content from the viewport edge.
            // Viewport-relative rather than a fixed negative margin because that ambient padding's
            // real value isn't owned by, or reliably knowable from, this file.
            width="100vw"
            position="relative"
            left="50%"
            right="50%"
            marginLeft="-50vw"
            marginRight="-50vw"
          >
            {group.cards.map(({ label, card, interactive }) => (
              // 288px isn't a registered token -- it's ZimmProductCardMedia's own documented
              // Figma "Large" sample width (zimmProductCardMedia.css.ts's ASPECT_RATIO comment).
              // Capped here as a max-width so the card's genuinely fluid image (width:100%,
              // aspectRatio 2/3 -- "fluid, not a fixed px width" per that same file) doesn't
              // stretch oversized when a fixed 4-column grid divides a wide viewport into columns
              // much wider than Figma's own reference render. justifyItems="center" above absorbs
              // the leftover column width evenly instead of pinning the card to one edge.
              <Box key={card.id} maxWidth="288px" width="100%">
                <Text
                  textStyle="label"
                  textTransform="uppercase"
                  color="var(--zimm-color-text-muted)"
                  marginBottom="var(--zimm-scale-xs)"
                >
                  {label}
                </Text>
                {interactive ? <DemoSizeSelectableCard {...card} /> : <ZimmProductCard {...card} />}
              </Box>
            ))}
          </SimpleGrid>
        </Box>
      ))}
    </Box>
  );
};

export default LiveProductCardDemoSection;

