1	/**
2	 * Pure mapping from a real `useProductSearch` hit to `ZimmProductCardProps`-shaped pieces, for the
3	 * temporary live homepage demo (`liveProductCardDemoSection.tsx`). No React/react-intl import, same
4	 * discipline `overrides/app/pages/product-detail/productInfo.ts` already establishes — a formatter
5	 * is injected as a parameter instead, so this stays independently callable/testable.
6	 *
7	 * Throwaway-demo scope note: this file intentionally does not attempt full type-safety against the
8	 * real `commerce-sdk-isomorphic` `ProductSearchHit` shape (AGENTS.md's "don't re-declare SDK types"
9	 * rule is aimed at production code) — the narrow, hand-rolled types below only declare the handful
10	 * of fields this demo actually reads, and every accessor degrades gracefully (returns `undefined`/
11	 * an empty array) rather than throwing when a real response doesn't have what's expected.
12	 */
13	import { filterImageGroups } from '@salesforce/retail-react-app/app/utils/product-utils';
14	import { productUrlBuilder } from '@salesforce/retail-react-app/app/utils/url';
15	import type {
16	  ZimmProductCardBaseProps,
17	  ZimmProductCardImage,
18	} from '../../components/ui-kits/organisms/zimmProductCard';
19	import type { ZimmSizeChipValue } from '../../components/ui-kits/molecules/zimmSizeChipGroup';
20	
21	export type LiveDemoImage = { link: string; disBaseLink?: string; alt?: string };
22	export type LiveDemoImageGroup = {
23	  viewType: string;
24	  variationAttributes?: Array<{ id: string; values?: Array<{ value: string }> }>;
25	  images: LiveDemoImage[];
26	};
27	export type LiveDemoVariationAttributeValue = { value: string; name?: string; orderable?: boolean };
28	export type LiveDemoVariationAttribute = {
29	  id: string;
30	  name?: string;
31	  values?: LiveDemoVariationAttributeValue[];
32	};
33	export type LiveDemoVariant = {
34	  productId: string;
35	  price?: number;
36	  orderable?: boolean;
37	  variationValues?: Record<string, string>;
38	};
39	export type LiveDemoSourceHit = {
40	  productId: string;
41	  productName?: string;
42	  price?: number;
43	  currency?: string;
44	  orderable?: boolean;
45	  imageGroups?: LiveDemoImageGroup[];
46	  variationAttributes?: LiveDemoVariationAttribute[];
47	  variants?: LiveDemoVariant[];
48	};
49	
50	/** Injected so this module stays free of react-intl, mirroring productInfo.ts's FormatPrice shape. */
51	export type FormatPrice = (amount: number, currency: string) => string;
52	
53	const COLOUR_ATTRIBUTE_ID = 'color';
54	const SIZE_ATTRIBUTE_ID = 'size';
55	
56	/** Picks the demo's one real, sellable line item: first orderable variant, else variants[0], else the master hit. */
57	export const resolveDemoVariant = (hit: LiveDemoSourceHit) => {
58	  const variant = hit.variants?.find((v) => v.orderable) ?? hit.variants?.[0];
59	  return {
60	    productId: variant?.productId ?? hit.productId,
61	    price: variant?.price ?? hit.price,
62	    colourCode: variant?.variationValues?.[COLOUR_ATTRIBUTE_ID],
63	    sizeCode: variant?.variationValues?.[SIZE_ATTRIBUTE_ID],
64	  };
65	};
66	
67	/** Cross-references a variation code (not a display name) against variationAttributes for its label. */
68	const resolveAttributeName = (hit: LiveDemoSourceHit, attributeId: string, code?: string): string | undefined =>
69	  hit.variationAttributes?.find((a) => a.id === attributeId)?.values?.find((v) => v.value === code)?.name;
70	
71	export type LiveDemoCardBase = {
72	  base: Pick<
73	    ZimmProductCardBaseProps,
74	    'href' | 'name' | 'headingLevel' | 'primaryImage' | 'hoverImage' | 'images' | 'currentPrice'
75	  >;
76	  colour?: string;
77	  size?: string;
78	  variantProductId: string;
79	  variantPrice?: number;
80	};
81	
82	/** Base fields shared by every demo card instance, built once per hit. Returns null if unusable. */
83	export const selectLiveProductCardBase = (
84	  hit: LiveDemoSourceHit,
85	  formatPrice: FormatPrice,
86	): LiveDemoCardBase | null => {
87	  if (!hit.productName) return null;
88	  const variant = resolveDemoVariant(hit);
89	  const colour = resolveAttributeName(hit, COLOUR_ATTRIBUTE_ID, variant.colourCode);
90	  const size = resolveAttributeName(hit, SIZE_ATTRIBUTE_ID, variant.sizeCode);
91	
92	  const groups = filterImageGroups(hit.imageGroups ?? [], {
93	    viewType: 'medium',
94	    variationValues: variant.colourCode ? { [COLOUR_ATTRIBUTE_ID]: variant.colourCode } : {},
95	  }) as LiveDemoImageGroup[];
96	  const groupImages = groups?.[0]?.images ?? [];
97	
98	  const toCardImage = (img: LiveDemoImage): ZimmProductCardImage => ({
99	    src: img.disBaseLink || img.link,
100	    // ZimmProductCardMediaImage.alt is required + non-empty (unlike base ProductTile's decorative
101	    // alt: '' convention) -- prefer SFCC's own alt when present, else synthesize from name+colour.
102	    alt: img.alt?.trim() || `${hit.productName}${colour ? `, ${colour}` : ''}`,
103	  });
104	
105	  return {
106	    base: {
107	      href: productUrlBuilder({ id: hit.productId }),
108	      name: hit.productName,
109	      headingLevel: 'h3',
110	      primaryImage: groupImages[0] ? toCardImage(groupImages[0]) : toCardImage({ link: '', alt: hit.productName }),
111	      hoverImage: groupImages[1] ? toCardImage(groupImages[1]) : undefined,
112	      images: groupImages.length > 1 ? groupImages.map(toCardImage) : undefined,
113	      // No hardcoded fallback currency -- if either is absent, skip formatting rather than guess.
114	      currentPrice:
115	        typeof variant.price === 'number' && hit.currency ? formatPrice(variant.price, hit.currency) : undefined,
116	    },
117	    colour,
118	    size,
119	    variantProductId: variant.productId,
120	    variantPrice: variant.price,
121	  };
122	};
123	
124	/**
125	 * Size-chip values for the interactive picker instances. The 'size' attribute id is the standard
126	 * SFCC convention but not independently confirmed against a live response this session (unlike
127	 * 'color', which is already an established literal elsewhere in this codebase) -- degrades to an
128	 * empty array rather than throwing if this org's real id differs.
129	 */
130	export const buildSizeChipValues = (hit: LiveDemoSourceHit): ZimmSizeChipValue[] =>
131	  (hit.variationAttributes?.find((a) => a.id === SIZE_ATTRIBUTE_ID)?.values ?? []).map((v) => ({
132	    value: v.value,
133	    label: v.name ?? v.value,
134	    isDisabled: v.orderable === false,
135	  }));
136	
137	/** Picks which of the fetched hits becomes the one reused demo product. */
138	export const pickDemoHit = (hits: LiveDemoSourceHit[]): LiveDemoSourceHit | undefined => {
139	  const imageCount = (hit: LiveDemoSourceHit) =>
140	    (filterImageGroups(hit.imageGroups ?? [], { viewType: 'medium', variationValues: {} }) as LiveDemoImageGroup[])?.[0]
141	      ?.images?.length ?? 0;
142	  const sizeCount = (hit: LiveDemoSourceHit) =>
143	    hit.variationAttributes?.find((a) => a.id === SIZE_ATTRIBUTE_ID)?.values?.length ?? 0;
144	  return hits.find((h) => imageCount(h) >= 2 && sizeCount(h) >= 2) ?? hits.find((h) => imageCount(h) >= 1) ?? hits[0];
145	};
146

