/**
 * Pure mapping from a real `useProductSearch` hit to `ZimmProductCardProps`-shaped pieces, for the
 * temporary live homepage demo (`liveProductCardDemoSection.tsx`). No React/react-intl import, same
 * discipline `overrides/app/pages/product-detail/productInfo.ts` already establishes — a formatter
 * is injected as a parameter instead, so this stays independently callable/testable.
 *
 * Throwaway-demo scope note: this file intentionally does not attempt full type-safety against the
 * real `commerce-sdk-isomorphic` `ProductSearchHit` shape (AGENTS.md's "don't re-declare SDK types"
 * rule is aimed at production code) — the narrow, hand-rolled types below only declare the handful
 * of fields this demo actually reads, and every accessor degrades gracefully (returns `undefined`/
 * an empty array) rather than throwing when a real response doesn't have what's expected.
 */
import { filterImageGroups } from '@salesforce/retail-react-app/app/utils/product-utils';
import { productUrlBuilder } from '@salesforce/retail-react-app/app/utils/url';
import type {
  ZimmProductCardBaseProps,
  ZimmProductCardImage,
} from '../../components/ui-kits/organisms/zimmProductCard';
import type { ZimmSizeChipValue } from '../../components/ui-kits/molecules/zimmSizeChipGroup';

export type LiveDemoImage = { link: string; disBaseLink?: string; alt?: string };
export type LiveDemoImageGroup = {
  viewType: string;
  variationAttributes?: Array<{ id: string; values?: Array<{ value: string }> }>;
  images: LiveDemoImage[];
};
export type LiveDemoVariationAttributeValue = { value: string; name?: string; orderable?: boolean };
export type LiveDemoVariationAttribute = {
  id: string;
  name?: string;
  values?: LiveDemoVariationAttributeValue[];
};
export type LiveDemoVariant = {
  productId: string;
  price?: number;
  orderable?: boolean;
  variationValues?: Record<string, string>;
};
export type LiveDemoSourceHit = {
  productId: string;
  productName?: string;
  price?: number;
  currency?: string;
  orderable?: boolean;
  imageGroups?: LiveDemoImageGroup[];
  variationAttributes?: LiveDemoVariationAttribute[];
  variants?: LiveDemoVariant[];
};

/** Injected so this module stays free of react-intl, mirroring productInfo.ts's FormatPrice shape. */
export type FormatPrice = (amount: number, currency: string) => string;

const COLOUR_ATTRIBUTE_ID = 'color';
const SIZE_ATTRIBUTE_ID = 'size';

/** Picks the demo's one real, sellable line item: first orderable variant, else variants[0], else the master hit. */
export const resolveDemoVariant = (hit: LiveDemoSourceHit) => {
  const variant = hit.variants?.find((v) => v.orderable) ?? hit.variants?.[0];
  return {
    productId: variant?.productId ?? hit.productId,
    price: variant?.price ?? hit.price,
    colourCode: variant?.variationValues?.[COLOUR_ATTRIBUTE_ID],
    sizeCode: variant?.variationValues?.[SIZE_ATTRIBUTE_ID],
  };
};

/** Cross-references a variation code (not a display name) against variationAttributes for its label. */
const resolveAttributeName = (hit: LiveDemoSourceHit, attributeId: string, code?: string): string | undefined =>
  hit.variationAttributes?.find((a) => a.id === attributeId)?.values?.find((v) => v.value === code)?.name;

export type LiveDemoCardBase = {
  base: Pick<
    ZimmProductCardBaseProps,
    'href' | 'name' | 'headingLevel' | 'primaryImage' | 'hoverImage' | 'images' | 'currentPrice'
  >;
  colour?: string;
  size?: string;
  variantProductId: string;
  variantPrice?: number;
};

/** Base fields shared by every demo card instance, built once per hit. Returns null if unusable. */
export const selectLiveProductCardBase = (
  hit: LiveDemoSourceHit,
  formatPrice: FormatPrice,
): LiveDemoCardBase | null => {
  if (!hit.productName) return null;
  const variant = resolveDemoVariant(hit);
  const colour = resolveAttributeName(hit, COLOUR_ATTRIBUTE_ID, variant.colourCode);
  const size = resolveAttributeName(hit, SIZE_ATTRIBUTE_ID, variant.sizeCode);

  const groups = filterImageGroups(hit.imageGroups ?? [], {
    viewType: 'medium',
    variationValues: variant.colourCode ? { [COLOUR_ATTRIBUTE_ID]: variant.colourCode } : {},
  }) as LiveDemoImageGroup[];
  const groupImages = groups?.[0]?.images ?? [];

  const toCardImage = (img: LiveDemoImage): ZimmProductCardImage => ({
    src: img.disBaseLink || img.link,
    // ZimmProductCardMediaImage.alt is required + non-empty (unlike base ProductTile's decorative
    // alt: '' convention) -- prefer SFCC's own alt when present, else synthesize from name+colour.
    alt: img.alt?.trim() || `${hit.productName}${colour ? `, ${colour}` : ''}`,
  });

  return {
    base: {
      href: productUrlBuilder({ id: hit.productId }),
      name: hit.productName,
      headingLevel: 'h3',
      primaryImage: groupImages[0] ? toCardImage(groupImages[0]) : toCardImage({ link: '', alt: hit.productName }),
      hoverImage: groupImages[1] ? toCardImage(groupImages[1]) : undefined,
      images: groupImages.length > 1 ? groupImages.map(toCardImage) : undefined,
      // No hardcoded fallback currency -- if either is absent, skip formatting rather than guess.
      currentPrice:
        typeof variant.price === 'number' && hit.currency ? formatPrice(variant.price, hit.currency) : undefined,
    },
    colour,
    size,
    variantProductId: variant.productId,
    variantPrice: variant.price,
  };
};

/**
 * Size-chip values for the interactive picker instances. The 'size' attribute id is the standard
 * SFCC convention but not independently confirmed against a live response this session (unlike
 * 'color', which is already an established literal elsewhere in this codebase) -- degrades to an
 * empty array rather than throwing if this org's real id differs.
 */
export const buildSizeChipValues = (hit: LiveDemoSourceHit): ZimmSizeChipValue[] =>
  (hit.variationAttributes?.find((a) => a.id === SIZE_ATTRIBUTE_ID)?.values ?? []).map((v) => ({
    value: v.value,
    label: v.name ?? v.value,
    isDisabled: v.orderable === false,
  }));

/** Picks which of the fetched hits becomes the one reused demo product. */
export const pickDemoHit = (hits: LiveDemoSourceHit[]): LiveDemoSourceHit | undefined => {
  const imageCount = (hit: LiveDemoSourceHit) =>
    (filterImageGroups(hit.imageGroups ?? [], { viewType: 'medium', variationValues: {} }) as LiveDemoImageGroup[])?.[0]
      ?.images?.length ?? 0;
  const sizeCount = (hit: LiveDemoSourceHit) =>
    hit.variationAttributes?.find((a) => a.id === SIZE_ATTRIBUTE_ID)?.values?.length ?? 0;
  return hits.find((h) => imageCount(h) >= 2 && sizeCount(h) >= 2) ?? hits.find((h) => imageCount(h) >= 1) ?? hits[0];
};

