import React, { useEffect, useRef, useState } from 'react';
import { chakra, useMultiStyleConfig } from '@chakra-ui/react';
import { defineMessages, useIntl } from 'react-intl';
import { ZimmSlideIndicator } from '../zimmSlideIndicator';
import { ChevronLeftIcon, ChevronRightIcon, CloseIcon } from '../../../icons';
import { CARD_SLOT } from '../../zimmProductCardShared';

/**
 * Selector contract for a later step (the ZimmProductCard organism, SFCC-236 Step 6): stable
 * `data-card-slot` values on this component's own DOM so that organism's own recipe can target
 * these descendants for hover-reveal styling without reaching into implementation details.
 * Do not rename these values without updating that recipe too:
 *   - "media"     — the outermost element (this component's root)
 *   - "badge"     — the merchandiser badge label, top-left of the image (present only when a
 *                   non-empty `badge` is supplied)
 *   - "close"     — the remove-CTA button (present only when `onRemove` + a usable label exist)
 *   - "carousel"  — the prev/next arrows wrapper (present only when paging is enabled)
 *   - "indicator" — the touch slide-indicator wrapper (present only when there is >1 image)
 */

const messages = defineMessages({
  previousImage: { id: 'product_card_media.pagination.previous', defaultMessage: 'Previous image' },
  nextImage: { id: 'product_card_media.pagination.next', defaultMessage: 'Next image' },
  /**
   * Accessible name for the always-available keyboard-operable scroll container (WCAG 2.1.1) —
   * distinct from the hover-capable-only `carousel` arrows and the touch-only
   * `indicatorWrapper`, this is the underlying paging affordance that exists regardless of
   * pointer capability. See `canNavigateByKeyboard` below.
   */
  galleryLabel: { id: 'product_card_media.gallery.label', defaultMessage: 'Product images' },
});

const ZIMM_PRODUCT_CARD_MEDIA_RECIPE = 'ZimmProductCardMedia';

/** One image the card can show — always a real, non-empty product-photo description. */
export type ZimmProductCardMediaImage = {
  src: string;
  alt: string;
};

export type ZimmProductCardMediaProps = {
  /** The image shown when nothing else applies — always required, even when `images` is supplied. */
  primaryImage: ZimmProductCardMediaImage;
  /**
   * The second image revealed on hover (desktop/hover-capable pointers only), crossfading with
   * `primaryImage`. Ignored while a multi-image `images` gallery is active (>1 entries) — the
   * arrows/indicator paging affordances already give a shopper a way to browse every image, so
   * a hover-swap of just the first two would be a second, inconsistent way to see the same
   * content. Has no effect unless `swapOnHover` is also true.
   */
  hoverImage?: ZimmProductCardMediaImage;
  /**
   * The full orderable gallery for this card. Only takes over from `primaryImage` when it has
   * more than one entry — 0 or 1 entries behaves exactly like an absent `images` (see
   * `hoverImage`'s note above for why the two features don't combine).
   */
  images?: ZimmProductCardMediaImage[];
  /** Enables the primary/hover crossfade described on `hoverImage`. Has no effect without it. */
  swapOnHover: boolean;
  /**
   * Enables the desktop prev/next arrows. The touch slide-indicator is independent of this flag
   * (per the Figma "Image Group" spec, the touch variant has no separate "controls off" state)
   * — it renders whenever there is more than one image to page through, regardless of this prop.
   */
  showControls: boolean;
  /**
   * Merchandiser-configured badge label (e.g. "Runway", "Exclusive") — SFCC-236's Figma "Tag"
   * overlay, top-left of the image. Renders only when non-empty; a blank/whitespace-only value
   * behaves identically to omitting the prop, same guard shape as `removeLabel` below. Which
   * variations actually show a badge (PLP/Wishlist yes, Home no) is the organism's job via its
   * `VARIATION_CONFIG` — this component only renders what it's given.
   */
  badge?: string;
  /** Wishlist-only remove action. Rendered only when paired with a usable `removeLabel`. */
  onRemove?: () => void;
  /**
   * Accessible name for the remove button — required in practice whenever `onRemove` is passed
   * (typically the product name, e.g. "Remove {productName} from wishlist"). Modelled as two
   * independent optional props rather than a discriminated union because this is a simple
   * co-requirement, not a real variant split: if `onRemove` is supplied without a usable
   * (non-empty, non-whitespace) `removeLabel`, the remove button silently does not render at
   * all rather than shipping an unlabelled, inaccessible button — see the component body.
   */
  removeLabel?: string;
  /**
   * LCP escape hatch for the primary image slot. Defaults to lazy-loading — this component has
   * no way to know whether it sits above the fold, so the safer default is lazy; a caller that
   * knows it renders above the fold (AGENTS.md's "LCP ≤2s p75 mobile" priority) should pass
   * `priority`. Has no effect on any non-primary image, which is always lazy regardless.
   */
  priority?: boolean;
  /**
   * Optional click handler on this component's own root — forwarded as-is, with no navigation
   * logic of its own (Media stays navigation-agnostic; the composing organism decides what a
   * click means and which of Media's own buttons to exclude from it). Added for SFCC-236 Fix I —
   * see the composing `ZimmProductCard` organism's own docblock for the full narrative.
   */
  onClick?: React.MouseEventHandler<HTMLDivElement>;
};

/**
 * Molecule — the product-card media block: a single image, a hover-swap pair, or a full
 * scroll-snap gallery with desktop arrows / touch slide-indicator, plus the wishlist-remove
 * overlay slot. Figma "Image Group" component set, node 40002742:46323.
 *
 * Touch paging is native CSS scroll-snap at every breakpoint; arrows are a progressive
 * enhancement over the same scroll container, never a second, independent mechanism. Arrows and
 * the slide indicator are mutually exclusive by pointer capability
 * (`(hover: hover) and (pointer: fine)`) and never both interactively visible at once. Both
 * exist in the DOM at all times, gated via CSS rather than a JS `window.matchMedia` check —
 * matching the "keep in DOM, hide via CSS" precedent `ZimmColourSwatchGroup` already uses for its
 * off-page swatches — so server and client render identically (no hydration mismatch) and
 * neither affordance depends on `matchMedia`, which jsdom (this component's own Vitest
 * environment) does not implement. The two affordances differ in *where* that CSS lives, though:
 * the indicator is fully gated by this recipe's own media query. The arrows are not — this
 * recipe only ever sets them to `display: none`; the actual reveal (`display: flex`, on
 * `&:hover`/`&:has(:focus-visible)`) lives in the composing `ZimmProductCard` organism's own recipe,
 * since the AC and Figma both specify arrows appear on an actual hover/focus interaction with the
 * whole card, not merely "device supports hover" — the same interaction-gated pattern already
 * used there for price/size-chips/notify-me. A story rendering this component standalone (see
 * this file's own `index.stories.tsx`) therefore never shows the arrows, by design.
 *
 * A third, always-available operability layer sits underneath both visual affordances: the
 * scroll container itself is keyboard-focusable and handles ArrowLeft/ArrowRight directly
 * whenever there is more than one slide, regardless of pointer capability or `showControls` —
 * a hover-incapable pointer previously had no way to page the gallery via keyboard at all
 * (WCAG 2.1.1), since the arrows are `display:none` there and the indicator has no focusable
 * content. See `canNavigateByKeyboard` / `handleScrollContainerKeyDown` below.
 */
export const ZimmProductCardMedia = ({
  primaryImage,
  hoverImage,
  images,
  swapOnHover,
  showControls,
  badge,
  onRemove,
  removeLabel,
  priority,
  onClick,
}: ZimmProductCardMediaProps) => {
  const intl = useIntl();
  const styles = useMultiStyleConfig(ZIMM_PRODUCT_CARD_MEDIA_RECIPE, {});

  // >1 entries takes over as the full slide list; 0 or 1 behaves like no gallery at all (see
  // the `images` prop's own JSDoc for why hover-swap and the gallery don't combine).
  const gallery = images && images.length > 1 ? images : undefined;
  const slideImages = gallery ?? [primaryImage];
  const totalSlides = slideImages.length;
  const showHoverSwap = swapOnHover && Boolean(hoverImage) && !gallery;
  const canPage = totalSlides > 1 && showControls;
  // Keyboard operability is independent of `showControls` — deliberately not folded into
  // `canPage` above (WCAG 2.1.1): a hover-incapable pointer (a touchscreen with a physical
  // keyboard attached, switch access, or a desktop browser reporting `hover:none`) has the
  // arrows hidden by the recipe's own media query and the indicator has no focusable content,
  // so this is the only paging affordance such a user has, regardless of `showControls`.
  const canNavigateByKeyboard = totalSlides > 1;

  // Single piece of state, per this codebase's extract-to-hook threshold
  // (.claude/rules/components.md). Kept inline — including the scroll-tracking and
  // index-clamping effects below — rather than pulled into a useProductCardMediaScroll hook,
  // because this build step's file manifest is limited to this component's own 4 files; a hook
  // would be a 5th file outside that scope.
  const [currentIndex, setCurrentIndex] = useState(0);
  const scrollContainerRef = useRef<HTMLDivElement>(null);

  const scrollToIndex = (index: number) => {
    const container = scrollContainerRef.current;
    if (!container || typeof container.scrollTo !== 'function') return;
    // clientWidth is 0 under jsdom (no real layout) — the call still fires with a plausible
    // {left, behavior} shape, which is what this component's own Vitest suite asserts; a real
    // browser reports a real width so the requested slide scrolls fully into view.
    container.scrollTo({ left: index * container.clientWidth, behavior: 'smooth' });
  };

  const goToRelativeSlide = (delta: 1 | -1) => {
    if (totalSlides <= 1) return;
    const next = (currentIndex + delta + totalSlides) % totalSlides;
    setCurrentIndex(next);
    scrollToIndex(next);
  };

  // Re-clamps currentIndex whenever the slide count shrinks while this instance stays mounted
  // (e.g. a colour-variant swap that reduces the gallery from 3 images to 2) — same "clamp to
  // the highest valid index" precedent as ZimmColourSwatchGroup's own page-clamp effect
  // (../zimmColourSwatchGroup/index.tsx:75-84). Without this, currentIndex stays at the stale,
  // out-of-range value: ZimmSlideIndicator's own display-side clamp masks it visually right
  // after the shrink, but goToRelativeSlide's modulo arithmetic above still computes from the
  // stale, unclamped state, so the very next Next/Previous click is a silent no-op.
  useEffect(() => {
    setCurrentIndex((index) => Math.min(index, totalSlides - 1));
  }, [totalSlides]);

  // Arrow-key paging on the scroll container itself, reachable regardless of pointer
  // capability — additive to, and independent of, the hover-capable-only arrows and the
  // touch-only indicator above (see canNavigateByKeyboard's own comment for why). Same
  // "check the key, then preventDefault" idiom as ZimmColourSwatchGroup's own
  // handleSwatchesKeyDown (../zimmColourSwatchGroup/index.tsx:109-111).
  const handleScrollContainerKeyDown = (event: React.KeyboardEvent<HTMLDivElement>) => {
    if (!['ArrowLeft', 'ArrowRight'].includes(event.key)) return;
    event.preventDefault();
    goToRelativeSlide(event.key === 'ArrowRight' ? 1 : -1);
  };

  // Keeps the touch slide-indicator's active dot following native swipe paging, which never
  // calls goToRelativeSlide at all. `scrollend` alone is not enough to do this live — that's
  // true on every browser, not just one lacking `scrollend` support: the event is only fired
  // once a scroll/snap gesture has fully *settled* (finger lifted, any momentum/snap animation
  // finished), so a dot driven by `scrollend` alone stays on the old slide for the whole
  // duration of an active drag and only jumps to the correct one once the gesture ends — a
  // real, user-visible lag, confirmed live once a related fix made the swipe gesture itself
  // reachable. `container.scrollLeft`, unlike `scrollend`, genuinely does update live while a
  // drag is in progress, so a `scroll` listener tracks it in real time — coalesced via
  // `requestAnimationFrame` so it updates at most once per animation frame, since native
  // touch-driven scrolling fires many `scroll` events per second and calling setState for
  // every one of them would be wasted work no frame could ever paint. `scrollend` stays
  // registered alongside `scroll`, unconditionally, as a final-correctness safety net — in
  // case the last in-frame scroll position during a fast gesture doesn't get its own
  // rAF-coalesced update before the browser is ready to fire the next one.
  useEffect(() => {
    const container = scrollContainerRef.current;
    if (!container || totalSlides <= 1) return undefined;

    const updateIndexFromScrollPosition = () => {
      const slideWidth = container.clientWidth || 1;
      const nearest = Math.round(container.scrollLeft / slideWidth);
      setCurrentIndex(Math.min(Math.max(nearest, 0), totalSlides - 1));
    };

    // `rafId` both throttles (skip scheduling a second frame while one is already pending) and
    // lets cleanup cancel a frame that hasn't fired yet if the component unmounts/re-runs first.
    let rafId: number | null = null;
    const handleScroll = () => {
      if (rafId !== null) return;
      rafId = requestAnimationFrame(() => {
        rafId = null;
        updateIndexFromScrollPosition();
      });
    };

    container.addEventListener('scroll', handleScroll, { passive: true });
    container.addEventListener('scrollend', updateIndexFromScrollPosition);
    return () => {
      container.removeEventListener('scroll', handleScroll);
      container.removeEventListener('scrollend', updateIndexFromScrollPosition);
      if (rafId !== null) cancelAnimationFrame(rafId);
    };
  }, [totalSlides]);

  // Non-primary images are always lazy; only the first slide's own base image can opt into
  // eager loading via `priority`. See that prop's own JSDoc for the default-to-lazy reasoning.
  const imageLoadingProps = (isPrimaryPosition: boolean): { loading?: 'lazy'; decoding: 'async' } =>
    isPrimaryPosition && priority ? { decoding: 'async' } : { loading: 'lazy', decoding: 'async' };

  const hasUsableRemoveLabel = typeof removeLabel === 'string' && removeLabel.trim().length > 0;
  const showRemove = Boolean(onRemove) && hasUsableRemoveLabel;
  const hasBadge = typeof badge === 'string' && badge.trim().length > 0;

  return (
    <chakra.div __css={styles.root} data-card-slot={CARD_SLOT.media} onClick={onClick}>
      <chakra.div
        ref={scrollContainerRef}
        __css={styles.scrollContainer}
        data-testid="card-media-scroll"
        role={canNavigateByKeyboard ? 'group' : undefined}
        aria-label={canNavigateByKeyboard ? intl.formatMessage(messages.galleryLabel) : undefined}
        tabIndex={canNavigateByKeyboard ? 0 : undefined}
        onKeyDown={canNavigateByKeyboard ? handleScrollContainerKeyDown : undefined}
      >
        {slideImages.map((image, index) => {
          const isPrimaryPosition = index === 0;

          if (isPrimaryPosition && showHoverSwap && hoverImage) {
            return (
              <chakra.div key={`${image.src}-${index}`} __css={styles.slide}>
                <chakra.img
                  src={image.src}
                  alt={image.alt}
                  data-role="hover-base"
                  __css={styles.hoverSwapBase}
                  {...imageLoadingProps(true)}
                />
                <chakra.img
                  src={hoverImage.src}
                  alt={hoverImage.alt}
                  data-role="hover-overlay"
                  __css={styles.hoverSwapOverlay}
                  {...imageLoadingProps(false)}
                />
              </chakra.div>
            );
          }

          return (
            <chakra.div key={`${image.src}-${index}`} __css={styles.slide}>
              <chakra.img
                src={image.src}
                alt={image.alt}
                __css={styles.image}
                {...imageLoadingProps(isPrimaryPosition)}
              />
            </chakra.div>
          );
        })}
      </chakra.div>

      {hasBadge && (
        <chakra.div __css={styles.badge} data-card-slot={CARD_SLOT.badge}>
          <chakra.span __css={styles.badgeLabel}>{badge}</chakra.span>
        </chakra.div>
      )}

      {showRemove && (
        <chakra.button
          type="button"
          __css={styles.close}
          data-card-slot={CARD_SLOT.close}
          aria-label={removeLabel}
          onClick={onRemove}
        >
          <CloseIcon aria-hidden boxSize="var(--zimm-icon-size-md)" />
        </chakra.button>
      )}

      {canPage && (
        <chakra.div __css={styles.carousel} data-card-slot={CARD_SLOT.carousel}>
          <chakra.button
            type="button"
            __css={styles.arrowButton}
            aria-label={intl.formatMessage(messages.previousImage)}
            onClick={() => goToRelativeSlide(-1)}
          >
            <ChevronLeftIcon aria-hidden />
          </chakra.button>
          <chakra.button
            type="button"
            __css={styles.arrowButton}
            aria-label={intl.formatMessage(messages.nextImage)}
            onClick={() => goToRelativeSlide(1)}
          >
            <ChevronRightIcon aria-hidden />
          </chakra.button>
        </chakra.div>
      )}

      {totalSlides > 1 && (
        <chakra.div __css={styles.indicatorWrapper} data-card-slot={CARD_SLOT.indicator}>
          <ZimmSlideIndicator count={totalSlides} activeIndex={currentIndex} />
        </chakra.div>
      )}
    </chakra.div>
  );
};

export default ZimmProductCardMedia;

import type { SystemStyleObject } from '@chakra-ui/react';
import { HOVER_CAPABLE_QUERY } from '../../zimmProductCardShared';

// Figma "Image Group" component set, node 40002742:46323. The Large variant (40002742:46322,
// 288x432) and the Small/mobile variant (40002742:46321, 179x268) both resolve to the same
// ~2:3 ratio (288/432 = 0.667; 179/268 = 0.668) — expressed here as a ratio, not either
// variant's sampled pixel dimensions, per the card's "fluid, not a fixed px width" contract.
const ASPECT_RATIO = '2 / 3';

// Arrows and the touch slide-indicator are mutually exclusive by pointer capability, matching
// the resolved SFCC-236 decision confirmed directly in the Figma structure: the Large
// (hover-capable) variant carries the Carousel arrows with no indicator; the Small (touch)
// variant carries the indicator with no Carousel. `HOVER_CAPABLE_QUERY` itself now lives in
// `zimmProductCardShared.ts` — shared with `zimmProductCard.css.ts`'s own identical gate — rather
// than being retyped here.

/**
 * Recipe for the product-card media block (ui-kits/molecules/zimmProductCardMedia). Parts:
 *   - `root` / `scrollContainer` / `slide` — the always-present scroll-snap structure.
 *   - `image` — a plain (non-hover-swap) slide's own <img>.
 *   - `hoverSwapBase` / `hoverSwapOverlay` — the two-layer crossfade pair used on the first
 *     slide only, when hover-swap is active. The `:hover` rule lives on `slide` itself (below)
 *     rather than on a dedicated wrapper part, since `slide` already establishes
 *     `position: relative` for every slide and an unmatched `[data-role]` selector on a
 *     non-hover-swap slide is a harmless no-op.
 *   - `badge` / `badgeLabel` — the merchandiser badge overlay, top-left of the image (Figma
 *     "Tag" > "touchContainer" > "Label", node confirmed identical across every Size/Type variant
 *     checked). Collapsed onto one wrapper rather than mirroring both Figma levels: the inner
 *     touchContainer only exists there to guarantee a tap target for an otherwise-interactive
 *     library component, and this badge is static text with nothing to tap.
 *     Figma's "Tag" is a *fixed* 48px-tall frame — exactly matching `close`'s own fixed 48px —
 *     with the text centred inside that fixed height, not padded outward by it. An earlier
 *     revision of this recipe used `paddingBlock` alone with no explicit height, which sizes the
 *     wrapper to padding + content instead (measured 64px) — same horizontal inset, but a
 *     genuinely different total height, so its centre-line landed 9px below `close`'s. Fixed by
 *     giving `badge` the same `height: var(--zimm-scale-1200)` (48px) `close` already uses, plus
 *     `display: flex; align-items: center` to centre the text within that fixed height the same
 *     way `close` centres its icon — not by padding.
 *   - `close` — the wishlist-remove overlay slot.
 *   - `carousel` / `arrowButton` — the desktop prev/next affordance.
 *   - `indicatorWrapper` — positions the composed ZimmSlideIndicator flush to the bottom edge.
 */
export const ZimmProductCardMedia = {
  parts: [
    'root',
    'scrollContainer',
    'slide',
    'image',
    'hoverSwapBase',
    'hoverSwapOverlay',
    'badge',
    'badgeLabel',
    'close',
    'carousel',
    'arrowButton',
    'indicatorWrapper',
  ],

  baseStyle: (): Record<string, SystemStyleObject> => ({
    root: {
      position: 'relative',
      width: '100%',
    },

    scrollContainer: {
      display: 'flex',
      width: '100%',
      overflowX: 'auto',
      scrollSnapType: 'x mandatory',
      // Safari touch scrolling needs this for scroll-snap to feel native — same precedent as
      // the base SFCC product-scroller's own scrollProps.sx.
      WebkitOverflowScrolling: 'touch',
      // This is a paged card surface, not a general-purpose scroll region — the indicator/
      // arrows are the visible paging affordance, so the native scrollbar is suppressed.
      scrollbarWidth: 'none',
      '&::-webkit-scrollbar': { display: 'none' },
      // Direct, mandatory consequence of this element now taking `tabIndex={0}` when
      // keyboard-navigable — same uniform ring every other interactive ui-kits/ control uses
      // (zimmColourSwatch, zimmNavItem, zimmColourSwatchGroup's pageButton).
      _focusVisible: {
        outline: 'var(--zimm-focus-ring)',
        outlineOffset: 'var(--zimm-focus-ring-offset-default)',
      },
    },

    slide: {
      position: 'relative',
      flex: '0 0 100%',
      width: '100%',
      aspectRatio: ASPECT_RATIO,
      scrollSnapAlign: 'start',
      overflow: 'hidden',
      [HOVER_CAPABLE_QUERY]: {
        '&:hover [data-role="hover-overlay"]': { opacity: 1 },
        '&:hover [data-role="hover-base"]': { opacity: 0 },
      },
    },

    image: {
      display: 'block',
      width: '100%',
      height: '100%',
      objectFit: 'cover',
    },

    hoverSwapBase: {
      display: 'block',
      width: '100%',
      height: '100%',
      objectFit: 'cover',
      position: 'absolute',
      inset: 0,
      opacity: 1,
      transition: 'opacity var(--zimm-motion-duration-default) var(--zimm-motion-easing-fades)',
    },

    hoverSwapOverlay: {
      display: 'block',
      width: '100%',
      height: '100%',
      objectFit: 'cover',
      position: 'absolute',
      inset: 0,
      opacity: 0,
      transition: 'opacity var(--zimm-motion-duration-default) var(--zimm-motion-easing-fades)',
    },

    badge: {
      position: 'absolute',
      top: 0,
      left: 0,
      // 48px — matches `close`'s own fixed height exactly, so both sit on the same vertical
      // centre-line (see this file's own docblock note above for why padding-only sizing broke
      // this).
      height: 'var(--zimm-scale-1200)',
      display: 'flex',
      alignItems: 'center',
      paddingInline: 'var(--zimm-scale-xl)', // 24px — Figma "Tag" horizontal inset
    },

    badgeLabel: {
      textStyle: 'caption',
      // Figma's own "Label" text node carries no uppercase transform, but confirmed badges are
      // uppercase regardless — applied explicitly rather than inherited from the node.
      textTransform: 'uppercase',
      color: 'var(--zimm-color-text-default)',
      whiteSpace: 'nowrap',
    },

    close: {
      position: 'absolute',
      top: 0,
      right: 0,
      width: 'var(--zimm-scale-1200)', // 48px — Figma "Close" overlay area
      height: 'var(--zimm-scale-1200)',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      background: 'transparent',
      border: 'none',
      padding: 0,
      cursor: 'pointer',
      // Same uniform ring every other interactive control in ui-kits/ uses (zimmColourSwatch,
      // zimmNavItem, zimmColourSwatchGroup's pageButton) — this overlay sits on top of a
      // photographic image with only the bare browser-default outline otherwise.
      _focusVisible: {
        outline: 'var(--zimm-focus-ring)',
        outlineOffset: 'var(--zimm-focus-ring-offset-default)',
      },
    },

    carousel: {
      position: 'absolute',
      top: '50%',
      left: 0,
      right: 0,
      transform: 'translateY(-50%)',
      // No `[HOVER_CAPABLE_QUERY]` override here — the real reveal lives entirely on
      // `ZimmProductCard`'s own organism recipe (`zimmProductCard.css.ts`'s `root` part), scoped
      // to `:hover`/`:has(:focus-visible)` on the whole card, not just this image — see that
      // file's docblock point 6. A `[HOVER_CAPABLE_QUERY]: { display: 'flex' }` sub-block used to
      // live on this part, which made the arrows visible PERMANENTLY on any hover-capable device
      // (a device-CAPABILITY check, not an actual-hover check) — confirmed a real bug against the
      // Jira AC ("...when on desktop and the user hovers, then the arrows appear") and live Figma
      // (the Carousel element is `hidden="true"` on every Default-state instance checked, visible
      // only on the matching Hover-state instance, for both PLP and Wishlist).
      //
      // Fix J (SFCC-236) converted this part's own base/default hidden state from `display: 'none'`
      // to `clipPath: 'inset(50%)'`, unconditionally — Fix K (CodeRabbit finding on PR #85,
      // verified correct before fixing) reverted that: this rule applies on EVERY pointer type,
      // including touch, which `HOVER_CAPABLE_QUERY` never matches — there is no reveal path on
      // that pointer type at all (the original, Figma-confirmed design: arrows are a
      // hover-capable-only affordance). Clip-path kept each `arrowButton` (a real, always-tabbable
      // `<button>`) permanently in the tab order on touch with no way to ever reveal it — reachable
      // by Tab (e.g. a tablet with an external keyboard) but invisible and inert forever. Back to
      // `display: 'none'` here for exactly the pointer types that can never reveal it; the
      // hover-capable override (where a reveal genuinely is possible) now lives on
      // `zimmProductCard.css.ts`'s own `[HOVER_CAPABLE_QUERY]` block instead — see that file's own
      // Fix K note.
      display: 'none',
      justifyContent: 'space-between',
      alignItems: 'center',
      paddingInline: 'var(--zimm-scale-300)', // 12px — Figma arrow insets (x=12 / x=252 of 288)
      // Lets clicks pass through the empty centre of this band to whatever sits beneath the
      // image (e.g. a future PDP link in the Step 6 organism); re-enabled per-button below.
      // Fix J belt-and-braces: zimmProductCard.css.ts's own organism recipe now ALSO explicitly
      // zeroes out pointerEvents on `[data-card-slot="carousel"] button` by default (re-enabling
      // it only on reveal) — see that file's own docblock point 6 note for why this part's
      // unconditional `display: none` used to make that unnecessary, and no longer does.
      pointerEvents: 'none',
    },

    arrowButton: {
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      width: 'var(--zimm-scale-600)', // 24px — Figma touchContainer, meets WCAG 2.5.8
      height: 'var(--zimm-scale-600)',
      background: 'transparent',
      border: 'none',
      padding: 0,
      cursor: 'pointer',
      pointerEvents: 'auto',
      // Same uniform ring every other interactive control in ui-kits/ uses (zimmColourSwatch,
      // zimmNavItem, zimmColourSwatchGroup's pageButton) — this overlay sits on top of a
      // photographic image with only the bare browser-default outline otherwise.
      _focusVisible: {
        outline: 'var(--zimm-focus-ring)',
        outlineOffset: 'var(--zimm-focus-ring-offset-default)',
      },
    },

    indicatorWrapper: {
      position: 'absolute',
      left: 0,
      right: 0,
      bottom: 0,
      display: 'block',
      [HOVER_CAPABLE_QUERY]: {
        display: 'none',
      },
    },
  }),
};

import React from 'react';
import { chakra, useMultiStyleConfig } from '@chakra-ui/react';
import { Link as RouteLink } from 'react-router-dom';
import { defineMessages, useIntl } from 'react-intl';
import { ZimmProductName } from '../../atoms/zimmProductName';
import { ZimmProductPrice } from '../../atoms/zimmProductPrice';
import { ZimmIcon } from '../../atoms/zimmIcon';
import { ZimmSizeChipGroup } from '../zimmSizeChipGroup';
import type { ZimmSizeChipValue } from '../zimmSizeChipGroup';
import { CARD_SLOT } from '../../zimmProductCardShared';

/**
 * Selector contract for a later step (the ZimmProductCard organism, SFCC-236 Step 6): stable
 * `data-card-slot` values on this component's own DOM so that organism's own recipe can target
 * these descendants for hover-reveal styling without reaching into implementation details.
 * Do not rename these values without updating that recipe too — mirrors the same contract
 * `zimmProductCardMedia/index.tsx` documents for its own slots:
 *   - "content"   — the outermost element (this component's root).
 *   - "price"     — the price wrapper. Always rendered regardless of variation; the organism's
 *                   own CSS is what shows/hides it on hover per variation (see the `showBag`/
 *                   `showSizeChips` props below), not this component.
 *   - "sizeChips" — the size-chip-group wrapper (present only when `showSizeChips` is true).
 *                   Always rendered in the DOM per Figma's `hidden=true` default on the "Size
 *                   Selector instance" node — the organism's hover-reveal CSS is what handles
 *                   visibility, not this component's own recipe (see zimmProductCardContent.css.ts).
 *   - "bag"       — the bag-button wrapper (present only when `showBag` is true). Added later
 *                   than the three above, for the organism's own mobile-breakpoint hide rule
 *                   (Figma: PLP/PDP's Mobile Card-content instances have the bag icon's `Icons`
 *                   frame `hidden="true"`; Desktop and Wishlist's own Mobile instance do not) — a
 *                   viewport-width concern, not a hover one, but the same
 *                   "this component always renders it, the organism's CSS decides visibility"
 *                   division of responsibility as the other slots.
 */

// Same import base SFCC's own swatch-group/swatch.jsx uses for its `RouteLink`, and the same
// reasoning zimmColourSwatch/index.tsx already documents: a router `Link` delivers "URL updates
// without a full page reload" for real. Confirmed directly (no overrides/app/components/link/
// directory exists on disk) — there is no overrides/.../link equivalent to reuse instead.
const ProductNameLink = chakra(RouteLink);

const messages = defineMessages({
  // Deliberately generic, not name-interpolated ("Add {name} to bag") — no such requirement was
  // given, and the visible product name already sits immediately to this button's left in the
  // same row, so the accessible name does not need to repeat it.
  addToBag: { id: 'product_card_content.bag.add_to_bag', defaultMessage: 'Add to bag' },
  // Figma node 40002163:41468 (Desktop, Hover, PLP/PDP, Unavailable=True) — an instance of the
  // shared CTA/Link atom (40001908:28374/40001908:28368) with its text swapped to "NOTIFY ME" in
  // this state. Authored here in sentence case, not literal caps, matching this codebase's
  // pattern of keeping translatable copy normal-case and letting the textStyle's CSS apply the
  // visual transform (see ZimmProductName's own normal-cased stories against `productNames`'
  // textTransform: 'uppercase') — `linkSm` was corrected to `textTransform: 'uppercase'` to
  // match (2026-09-03, theme/foundation/typography.ts), so this renders "NOTIFY ME" correctly.
  notifyMe: {
    id: 'product_card_content.notify_me.label',
    defaultMessage: 'Notify me',
  },
});

const ZIMM_PRODUCT_CARD_CONTENT_RECIPE = 'ZimmProductCardContent';

/**
 * `ZimmProductName`'s own heading-level prop, read off the atom's real signature via a utility
 * type rather than a hand-typed duplicate union (typescript.md: "prefer utility types over
 * hand-rolled duplicate shapes... a hand-copied type silently drifts from its source when the
 * original changes"). Its type param is `'h1' | 'h2' | 'h3'` — note this is NOT `'h2' | 'h3' |
 * 'h4'` as an earlier sketch of this component's contract assumed; see `headingLevel` below.
 */
type ZimmProductNameHeadingLevel = React.ComponentProps<typeof ZimmProductName>['as'];

export type ZimmProductCardContentProps = {
  /** The product's display name, rendered as the card's heading and link text. */
  name: string;
  /**
   * Heading level for the composed `ZimmProductName`, forwarded to it as `as`. Named
   * `headingLevel` here (rather than `as`) because this component is not itself polymorphic —
   * it always renders the same fixed element tree, it just hands the one real heading a level.
   * Typed as `ZimmProductNameHeadingLevel` (`'h1' | 'h2' | 'h3'`) to exactly match what that atom
   * actually accepts — a prior sketch of this contract assumed `'h2' | 'h3' | 'h4'`, which is
   * wrong on both ends: the atom has no `'h4'` at all, and it does accept `'h1'` (unlikely in
   * practice for a grid card, but not this component's place to forbid what the atom allows).
   */
  headingLevel: ZimmProductNameHeadingLevel;
  /**
   * PDP destination for the product name link. Not passed through `isSafeHref` — unlike
   * `ZimmNavItem`/`ZimmContactIconRow`'s CMS-sourced hrefs, this is an SFCC-generated product URL,
   * the same trust level `ZimmColourSwatch`'s own `href` prop already assumes.
   */
  href: string;
  /** Passed straight through to the composed `ZimmProductPrice`. */
  currentPrice?: string;
  /** Passed straight through to the composed `ZimmProductPrice`. */
  originalPrice?: string;
  /** Passed straight through to `ZimmProductPrice`'s own `isLoading`. */
  isPriceLoading?: boolean;

  /**
   * Wishlist-only attributes line (colour + size as plain text), per the organism's
   * VARIATION_CONFIG (Step 6, not built yet) — this component only ever sees the resolved
   * boolean, never a variation name. When false the row is absent from the DOM entirely, not
   * merely visually hidden.
   */
  showAttributes: boolean;
  /**
   * Rendered only when `showAttributes` is true. Pass the plain colour value ("Ivory", not
   * "Ivory,") — the component itself appends the trailing comma when rendering, matching
   * Figma's own text-node structure (confirmed via get_design_context on node 40002187:58446:
   * the colour text node's own content literally includes the trailing comma, e.g. "Lilac
   * Sand,", not a separate punctuation node). See the `colourWithComma` derivation below.
   */
  colour?: string;
  /** Rendered only when `showAttributes` is true. */
  size?: string;

  /** Renders the bag button (Figma "Icon_bag" — confirmed a bag action, not a wishlist star). */
  showBag: boolean;
  /** Disables the bag button (native `disabled`) when true. `onAddToBag` never fires in that state. */
  isUnavailable?: boolean;
  onAddToBag?: () => void;

  /**
   * PLP-only size-chip picker, per the organism's config. Always rendered in the DOM whenever
   * true — Figma's `hidden=true` default on this slot is a hover-reveal CSS concern for the
   * Step 6 organism, not something this component enforces on itself. See the module docblock's
   * `data-card-slot="sizeChips"` note.
   */
  showSizeChips: boolean;
  sizeChipValues?: ZimmSizeChipValue[];
  selectedSizeChipValue?: string;
  onSizeChipSelect?: (value: string) => void;

  /**
   * True only when the caller has already resolved "unavailable AND a usable notify-me callback
   * exists" (the organism's job). This component still independently requires `onNotifyMe` to be
   * present before rendering anything — belt-and-braces, the same defensive shape
   * `ZimmProductCardMedia`'s own `onRemove` + `removeLabel` co-requirement uses.
   */
  showNotifyMe: boolean;
  onNotifyMe?: () => void;
};

/**
 * Molecule — the product-card text-content block: heading/link, bag action, wishlist-only
 * colour/size attributes, price, PLP-only size-chip picker, and an out-of-stock notify-me CTA.
 * Figma "Card-content" component set, node 40002109:26908 (Desktop 40002109:26906 / Mobile
 * 40002163:37103).
 *
 * Deliberately has NO remove/close button — that action lives entirely in
 * `ZimmProductCardMedia`'s own `close` overlay (Step 4), positioned on the image, not here.
 *
 * Also deliberately has no badge slot, despite the SFCC-236 AC mentioning one for PLP/Wishlist.
 * An earlier revision of this paragraph claimed no Figma design existed for it at all — that
 * was wrong: the badge (Figma "Tag") does exist, confirmed present and identical across every
 * Size/Type variant checked. It just lives inside "Image Group", which is
 * `ZimmProductCardMedia`'s domain, not this component's — so it was built there instead. See
 * that component's own docblock for the confirmed spec, and the organism's own docblock
 * ("Badge" note) for which variations actually show it.
 *
 * Composes `ZimmProductPrice` with `isLive={false}` unconditionally — this is the entire reason
 * that prop exists (SFCC-236 Step 3): a grid of these on a PLP must not mount dozens of
 * `aria-live` regions whose price never changes post-mount.
 */
export const ZimmProductCardContent = ({
  name,
  headingLevel,
  href,
  currentPrice,
  originalPrice,
  isPriceLoading,
  showAttributes,
  colour,
  size,
  showBag,
  isUnavailable,
  onAddToBag,
  showSizeChips,
  sizeChipValues,
  selectedSizeChipValue,
  onSizeChipSelect,
  showNotifyMe,
  onNotifyMe,
}: ZimmProductCardContentProps) => {
  const intl = useIntl();
  // `disabled`, not `isUnavailable` — matches `recipeGuards.test.ts`'s own `DEFAULT_STYLE_PROPS`
  // key so that guard's exhaustive prop-combination walk actually exercises both the true and
  // false branch of `bagButton`'s disabled styling (see zimmProductCardContent.css.ts's own
  // comment, and `zimmSizeChip.css.ts`'s identical `disabled` naming for the same reason).
  const styles = useMultiStyleConfig(ZIMM_PRODUCT_CARD_CONTENT_RECIPE, { disabled: isUnavailable });

  // Both conditions required, matching the component contract exactly — not just `showNotifyMe`
  // alone, so an organism that sets the flag without wiring a real callback silently renders
  // nothing rather than an inert button.
  const showNotifyMeButton = showNotifyMe && Boolean(onNotifyMe);

  // Figma renders the colour/size attributes line as ONE continuous phrase, not two independent
  // labels: the comma is baked into the colour text node's own content ("Lilac Sand,"), not a
  // separate punctuation element — confirmed via get_design_context on node 40002187:58446 (the
  // real Wishlist Card-content instance). Reproduced the same way here, on the colour value's own
  // rendered string (never as a static comma JSX node between the two spans), paired with
  // attributesRow's 2px gap (zimmProductCardContent.css.ts) for the "Ivory, M" breathing room —
  // verified by rendering the real Futura Round Medium caption style at actual size: the glyph
  // ink-to-ink gap the 2px flex gap produces here reads as a genuine (if slightly tighter than
  // full-prose) space, not as "Ivory,M" touching. Guarded against `colour` being falsy so a
  // caller omitting it (a contract violation, but not this component's job to enforce) still
  // renders nothing, rather than the literal string "undefined,".
  const colourWithComma = colour ? `${colour},` : colour;

  return (
    <chakra.div __css={styles.root} data-card-slot={CARD_SLOT.content}>
      <chakra.div __css={styles.nameRow}>
        <ProductNameLink to={href} __css={styles.nameLink}>
          <ZimmProductName name={name} as={headingLevel} />
        </ProductNameLink>

        {showBag && (
          <chakra.div __css={styles.bagWrapper} data-card-slot={CARD_SLOT.bag}>
            <chakra.button
              type="button"
              __css={styles.bagButton}
              aria-label={intl.formatMessage(messages.addToBag)}
              disabled={isUnavailable}
              onClick={() => {
                // Belt-and-braces: the native `disabled` attribute already prevents the browser
                // from ever dispatching this click, but stating the invariant explicitly means a
                // reader doesn't have to recall that fact to trust onAddToBag can't fire while
                // unavailable. Same idiom as ZimmSizeChip's own onClick guard.
                if (isUnavailable) return;
                onAddToBag?.();
              }}
            >
              <ZimmIcon type="bag" aria-hidden />
            </chakra.button>
          </chakra.div>
        )}
      </chakra.div>

      {showAttributes && (
        <chakra.div __css={styles.attributesRow} data-testid="card-content-attributes">
          <chakra.span __css={styles.colourText}>{colourWithComma}</chakra.span>
          <chakra.span __css={styles.sizeText}>{size}</chakra.span>
        </chakra.div>
      )}

      <chakra.div __css={styles.priceWrapper} data-card-slot={CARD_SLOT.price}>
        <ZimmProductPrice
          currentPrice={currentPrice}
          originalPrice={originalPrice}
          isLoading={isPriceLoading}
          isLive={false}
        />
      </chakra.div>

      {showSizeChips && (
        <chakra.div __css={styles.sizeChipWrapper} data-card-slot={CARD_SLOT.sizeChips}>
          <ZimmSizeChipGroup
            values={sizeChipValues ?? []}
            selectedValue={selectedSizeChipValue}
            onSelect={onSizeChipSelect}
          />
        </chakra.div>
      )}

      {showNotifyMeButton && (
        <chakra.button
          type="button"
          __css={styles.notifyMeButton}
          onClick={onNotifyMe}
          data-card-slot={CARD_SLOT.notifyMe}
        >
          {intl.formatMessage(messages.notifyMe)}
        </chakra.button>
      )}
    </chakra.div>
  );
};

export default ZimmProductCardContent;

import React from 'react';
import { chakra, useMultiStyleConfig } from '@chakra-ui/react';
import { useIntl } from 'react-intl';

const ZIMM_PRODUCT_PRICE_RECIPE = 'ZimmProductPrice';

/*
 * The labels are UI copy, so they are translatable messages rather than literals. `defaultMessage`
 * carries the English inline, which is what makes this work with no `translations/` entry: that
 * directory is Tier 2 (owner Integration/SI Partner) and is populated by the extraction step, so
 * a component cannot add to it. Until extraction runs, every locale renders `defaultMessage`;
 * once it does, the non-English storefronts pick up their own strings with no change here.
 *
 * The ids follow the base template's namespace for PDP labels — `product_view.label.quantity`
 * and `product_view.label.variant_type` are its siblings — so a translator finds them with the
 * rest of the PDP copy.
 *
 * Placeholder syntax `{price}` lets a locale reorder the price relative to the label
 * (e.g. German might prefer "595,00 € war" — Was after the figure).
 */
const WAS_PRICE_MESSAGE = {
  id: 'product_view.label.was_price',
  defaultMessage: 'Was {price}',
};
const NOW_PRICE_MESSAGE = {
  id: 'product_view.label.now_price',
  defaultMessage: 'Now {price}',
};

type ZimmProductPriceProps = {
  /**
   * The price the shopper pays today, already formatted by the caller (`intl.formatNumber`
   * at the page). This atom does no formatting of its own so it stays usable from Storybook
   * without an intl provider.
   * — Full price: the only price shown.
   * — On sale: rendered as the "Now" figure alongside `originalPrice`.
   *
   * Optional because the page's mapper resolves an absent price to `''` rather than to a
   * formatted `NaN` — see `pages/product-detail/productInfo.ts`'s `selectPdpProductInfo` and
   * the assertion it carries in `productInfo.test.ts`. That empty string reaches this atom
   * unchanged and the decision not to render is taken here.
   */
  currentPrice?: string;
  /**
   * The original full price before the sale, formatted the same way as `currentPrice`.
   * When supplied the atom switches to the Was/Now sale treatment (PRC-09):
   * "Was {originalPrice} Now {currentPrice}". Absent for full-price items.
   */
  originalPrice?: string;
  /**
   * When true, renders an empty container instead of the price — used while a variant
   * re-fetch is in progress to preserve the layout slot without showing stale Was/Now values.
   */
  isLoading?: boolean;
  /**
   * Opt out of the WCAG 4.1.3 live-region announcement (`aria-live`/`aria-atomic`) entirely.
   * Defaults to `true` so every existing caller (the PDP, where a variant swap needs to be
   * announced) keeps today's behaviour unchanged with no code change on their end. Pass `false`
   * when this atom is reused inside a grid of many cards (e.g. a PLP) where the price never
   * changes after mount, so a live region adds DOM/AT overhead for no benefit — the attributes
   * are omitted entirely in that case, not set to `aria-live="off"`.
   */
  isLive?: boolean;
};

/**
 * Atom — the single, full product price. All styling, type included, lives in
 * `zimmProductPrice.css.ts` and is consumed through the theme, per the
 * one-canonical-styling-surface rule. Type in particular must stay there rather than on the
 * element, or SFCC-194's `sale` variant cannot override it with a composite `textStyle` of its
 * own — see that file's docblock.
 *
 * Renders nothing when there is no price, so a caller can place it unconditionally — the same
 * contract as `ZimmProductDescription`. Rendering an empty `<p>` instead would still take a
 * flex `gap` in `ZimmProductContent`'s column, leaving a hole where the price should be.
 */
export const ZimmProductPrice = ({ currentPrice, originalPrice, isLoading, isLive = true }: ZimmProductPriceProps) => {
  // During loading, always use the sale variant so the flex row + two-span structure is rendered
  // (invisible) — this preserves the exact Was/Now dimensions while the fetch is in flight.
  const variant = isLoading || originalPrice ? 'sale' : 'default';

  // Guard below the hook, never above it: an early return before `useMultiStyleConfig` makes
  // the hook call conditional, which `react-hooks/rules-of-hooks` reports as an error rather
  // than a warning. Same ordering as `ZimmProductDescription` and `ZimmProductStyleCode`.
  const styles = useMultiStyleConfig(ZIMM_PRODUCT_PRICE_RECIPE, { variant });
  // `intl.formatMessage`, not a destructured `{ formatMessage }`: destructuring a method off
  // `useIntl()` trips `@typescript-eslint/unbound-method`. See `zimmProductStyleCode/index.tsx`
  // for the established pattern and why `useUiCopy` is wrong here.
  const intl = useIntl();

  // `isLive` gates both render paths below identically — omitted entirely when `false`, not
  // set to `aria-live="off"`, since a card-grid reuse (SFCC-236) has no live-region need at all
  // rather than an explicitly-disabled one.
  const liveRegionProps: { 'aria-live'?: 'polite'; 'aria-atomic'?: 'true' } = isLive
    ? { 'aria-live': 'polite', 'aria-atomic': 'true' }
    : {};

  // Preserve the full Was/Now layout slot while a variant re-fetch is in progress.
  // opacity:0 keeps the element in the flow (height + gap retained), hides the placeholder
  // content visually, and keeps it in the accessibility tree — so AT registers the live
  // region before the price arrives and announces the update when the fetch settles.
  // visibility:hidden was not used: it removes the element from the AT, defeating the
  // live-region purpose even though aria-hidden is absent.
  if (isLoading) {
    return (
      <chakra.p __css={styles.container} opacity={0} data-testid="product-price" {...liveRegionProps}>
        <chakra.span __css={styles.wasPrice}> </chakra.span> <chakra.span __css={styles.nowPrice}> </chakra.span>
      </chakra.p>
    );
  }

  if (!currentPrice) return null;

  return (
    /*
     * `aria-live`/`aria-atomic` sit on the price element itself, so this atom still renders
     * exactly one node.
     *
     * WCAG 2.2 AA 4.1.3 (Status Messages) is the requirement. Choosing a variant rewrites the
     * URL's `pid` (`pages/product-detail/index.tsx` lines 379-389), which re-keys the
     * `useProduct` call on line 204 and hands this atom a different string. Focus never moves,
     * so without a live region the price is repainted silently and a screen-reader user is never
     * told the number they are buying at has changed. React mutates this element's text in
     * place, which is exactly the change a live region reports; `aria-atomic` makes it read the
     * whole price rather than only the characters that differ.
     *
     * Base `display-price/current-price.jsx` instead puts the announcement in a second, hidden
     * node (its lines 57-66). It needs one because it prefixes a `labelForA11y` product name to
     * order the name ahead of the price (its comment on line 56); this atom has no such prefix
     * to order — `currentPrice` arrives already formatted and localised by the page and there is
     * no `useIntl` here — so the extra node would carry a verbatim duplicate of the visible text.
     * That costs twice: every screen reader would read the price twice on first load, and the
     * extra child breaks `ZimmProductContent`'s `play` tests, which assert the exact child count
     * of its flex column (`WithoutDescription`, `RhythmWithDescription`, `BlankDescription`).
     */
    <chakra.p __css={styles.container} data-testid="product-price" {...liveRegionProps}>
      {originalPrice ? (
        <>
          {/* PRC-09 Was/Now treatment — Figma node 40001028:9179 */}
          <chakra.span __css={styles.wasPrice} data-testid="product-was-price">
            {intl.formatMessage(WAS_PRICE_MESSAGE, { price: originalPrice })}
          </chakra.span>
          {/*
            A real space so `textContent` — what a screen reader reads with aria-atomic and
            what a shopper copies — is "Was $795.00 Now $595.00" with a separator. A
            whitespace-only flex item adds no width (CSS Flexbox §4), so the recipe's `gap`
            remains the only visual spacing between the spans.
          */}{' '}
          <chakra.span __css={styles.nowPrice} data-testid="product-now-price">
            {intl.formatMessage(NOW_PRICE_MESSAGE, { price: currentPrice })}
          </chakra.span>
        </>
      ) : (
        currentPrice
      )}
    </chakra.p>
  );
};

import type { SystemStyleObject } from '@chakra-ui/react';

/**
 * Multi-part recipe for the PDP price — parts: container, wasPrice, nowPrice.
 *
 * Converted from single-part (`useStyleConfig`) to multi-part (`useMultiStyleConfig`) so the
 * Was/Now span colours can be declared here and applied via `__css` in the component, rather
 * than via inline `sx` props. The `sale` variant styles all three parts; `default` only needs
 * the container (the spans never render in that variant).
 *
 * `textStyle` is declared in `baseStyle.container` rather than on the JSX element — if it
 * were on the element, a `sale` variant setting its own composite `textStyle` would be
 * displaced. `toCSSObject` resolves `assignAfter({}, __css, finalBaseStyle, filterUndefined(styleProps), sx)`
 * (dist/index.js lines 204-213), so an element `textStyle=` wins over the recipe — see the
 * original single-part docblock for the full explanation.
 */
export const ZimmProductPrice = {
  parts: ['container', 'wasPrice', 'nowPrice'],

  baseStyle: {
    container: {
      margin: 0,
      color: 'var(--zimm-color-text-default)',
      textStyle: 'price',
    } satisfies SystemStyleObject,
    // Stubs so every declared part is present in baseStyle — the invariant
    // zimmTextInput.css.test.ts:81-84 asserts for all multipart recipes. wasPrice and nowPrice
    // carry no base styling (they are sale-variant only), but omitting them would break
    // variant application: Chakra gates variant resolution through the declared parts list.
    wasPrice: {} satisfies SystemStyleObject,
    nowPrice: {} satisfies SystemStyleObject,
  },

  variants: {
    default: {},

    // PRC-09: Was/Now sale treatment. Colours and layout per Figma pdp/price (40001132:7331).
    // container → inline-flex row; gap/align-items/font per the Figma component spec.
    // wasPrice  → alias/color/text/subtlest (#969696) = text.muted / grey[300], 2.96:1 on white.
    //             Below the 4.5:1 AA threshold — a considered call by the FE lead to match the
    //             design system, logged here so it isn't mistaken for drift.
    // nowPrice  → alias/color/text/success (#2d5a3d) = status.success, 7.95:1 on white — WCAG AA.
    //             A semantic `text.success` alias would be cleaner but requires UI-designer
    //             sign-off (Hard Rule #3) and resolves to the same value — deferred.
    sale: {
      container: {
        display: 'inline-flex',
        // Allows the wasPrice/nowPrice spans to drop to their own line when they don't both
        // fit — e.g. a narrow PLP/mobile card column. Deliberately unconditional, not gated
        // behind DESKTOP_QUERY: WCAG 1.4.10 (Reflow) applies at any viewport width once zoomed
        // to a 320px-equivalent, so a desktop-only nowrap would still fail at high zoom there.
        // `whiteSpace: 'nowrap'` below is unaffected by this and still does its own job (keeping
        // each span's own "Was"/price or "Now"/price text from breaking internally) — the bug
        // was the missing flexWrap, not the whiteSpace.
        flexWrap: 'wrap',
        gap: 'var(--zimm-scale-xs)',
        alignItems: 'center',
        whiteSpace: 'nowrap',
        // Reserves the price's line box so the isLoading placeholder holds its layout slot.
        // The loading spans contain only a collapsible space, which generates no line box in
        // a flex container, so without this the <p> measures 0px and the page shifts ~18px
        // when the variant price settles. Same failure mode and remedy as
        // staticProductHeader.tsx's Skeleton minHeight.
        minHeight: 'var(--zimm-font-lineheight-2xs)',
      } satisfies SystemStyleObject,
      wasPrice: {
        color: 'var(--zimm-color-text-muted)',
      } satisfies SystemStyleObject,
      nowPrice: {
        color: 'var(--zimm-color-status-success)',
      } satisfies SystemStyleObject,
    },
  },

  defaultProps: {
    variant: 'default',
  },
};

import type { SystemStyleObject } from '@chakra-ui/react';
// Shared with zimmProductCard.css.ts's own identical need (its PLP bag-icon mobile hide) —
// extracted to zimmProductCardShared.ts for the same reason HOVER_CAPABLE_QUERY already is there:
// a module-private copy in each file is exactly the same-value-typed-twice drift risk a shared
// constant removes. See that module's own comment for why the underlying breakpoints token has
// to be imported directly rather than referenced as var(--zimm-*) — media queries can't consume
// CSS custom properties.
import { DESKTOP_QUERY } from '../../zimmProductCardShared';

/** State the atom feeds in so the recipe can resolve the bag button's disabled treatment —
 *  named `disabled`, not `isUnavailable`, to match `recipeGuards.test.ts`'s own
 *  `DEFAULT_STYLE_PROPS` key so that guard's exhaustive prop-combination walk actually exercises
 *  both branches. Same reasoning `zimmSizeChip.css.ts` documents for its own `disabled` prop. */
type ZimmProductCardContentStyleProps = {
  disabled?: boolean;
};

// Same uniform ring every other interactive control in ui-kits/ uses (zimmColourSwatch,
// zimmNavItem, zimmColourSwatchGroup's pageButton, zimmProductCardMedia's close/arrowButton/
// scrollContainer) — no Figma spec exists for focus on any of this component's three
// interactive parts (nameLink, bagButton, notifyMeButton), same situation those precedents were
// already in. This gap was caught twice already in this build (Step 2, Step 4); not repeating it.
const FOCUS_VISIBLE: SystemStyleObject = {
  outline: 'var(--zimm-focus-ring)',
  outlineOffset: 'var(--zimm-focus-ring-offset-default)',
};

/**
 * Recipe for the product-card text-content block (ui-kits/molecules/zimmProductCardContent).
 * Figma "Card-content" component set, node 40002109:26908 (Desktop 40002109:26906).
 *
 * Vertical rhythm is expressed as `marginTop` on each row rather than a uniform `root.gap`,
 * because the confirmed Figma offsets are NOT uniform:
 *   - 16px between the name row (height 25) and the attributes row (starts at y=41): 41-25=16.
 *   - 24px between the name+attributes block (height 49) and the price (starts at y=73): 73-49=24.
 *   - 24px between the price frame (height 82) and the (hidden by default) size-selector slot
 *     (starts at y=106): 106-82=24.
 * These margins apply regardless of which sibling actually precedes a given row (e.g. price's
 * marginTop is the same whether or not the attributes row rendered above it) — no distinct value
 * is confirmed for that specific combination, so the same rhythm is reused rather than invented.
 *
 * `root`'s outer padding IS genuinely responsive — a real, confirmed gap, not a missing
 * responsive split on an otherwise-correct single value. An earlier revision of this docblock
 * asserted nothing correctness-critical differed by breakpoint and shipped `root` with no
 * padding at all, on any breakpoint; that claim was never actually checked against the Mobile
 * variant and is corrected now that it has been. Confirmed via get_design_context on the two
 * real assembled card instances (not just the standalone documentation set):
 *   - Desktop (node 40002163:41443, the real assembled Desktop/Default/PLP-PDP card's
 *     Card-content): padding-top 32px, padding-inline 40px.
 *   - Mobile (node 40002163:37103, the Mobile Card-content variant): padding-top 16px,
 *     padding-inline 32px.
 * These are genuinely different values, not the same padding read at a smaller viewport, so
 * `root` carries an explicit `DESKTOP_QUERY` step (mobile-first: the
 * base values are the Mobile ones, overridden at the desktop breakpoint) rather than a single
 * baseStyle value — see .claude/rules/overrideStyling.md's "explicit media queries, not
 * Chakra's array shorthand" rule.
 *
 * Parts:
 *   - `root` — the outermost flex column; carries the responsive outer padding above.
 *   - `nameRow` — Figma's "Product name and icons": the heading link + bag icon, space-between.
 *   - `nameLink` — the router `<Link>` wrapping the composed ZimmProductName heading.
 *   - `bagWrapper` / `bagButton` — Figma's "Icons" group and its 24x24 `touchContainer` button.
 *   - `attributesRow` / `colourText` / `sizeText` — the wishlist-only colour/size meta line.
 *   - `priceWrapper` — wraps the composed ZimmProductPrice (always rendered).
 *   - `sizeChipWrapper` — wraps the composed ZimmSizeChipGroup (PLP-only when rendered at all).
 *   - `notifyMeButton` — the out-of-stock notify-me CTA, the shared CTA/Link atom instance
 *     (Figma node 40002163:41468; full citation in index.tsx).
 */
export const ZimmProductCardContent = {
  parts: [
    'root',
    'nameRow',
    'nameLink',
    'bagWrapper',
    'bagButton',
    'attributesRow',
    'colourText',
    'sizeText',
    'priceWrapper',
    'sizeChipWrapper',
    'notifyMeButton',
  ],

  baseStyle: ({ disabled }: ZimmProductCardContentStyleProps): Record<string, SystemStyleObject> => ({
    root: {
      display: 'flex',
      flexDirection: 'column',
      width: '100%',
      // Mobile-first base values — Figma node 40002163:37103 (Mobile Card-content variant).
      // See the module docblock above for the full citation and why this genuinely differs by
      // breakpoint rather than collapsing to one value.
      paddingTop: 'var(--zimm-scale-m)', // 16px
      paddingInline: 'var(--zimm-scale-2xl)', // 32px
      [DESKTOP_QUERY]: {
        // Desktop override — Figma node 40002163:41443 (Desktop/Default/PLP-PDP Card-content).
        paddingTop: 'var(--zimm-scale-2xl)', // 32px
        paddingInline: 'var(--zimm-scale-3xl)', // 40px
      },
    },

    nameRow: {
      display: 'flex',
      // 'center', not Figma codegen's own `items-start` approximation for this auto-layout row:
      // the "Card heading" (name) and "Icons" touchContainer resolve to different effective
      // heights in the real assembled card (name: 8px padding around a 16px line-height ≈ 32px;
      // icon: 4px padding around a 16px icon = 24px) — confirmed via get_design_context on node
      // 40002163:41441, the real assembled Desktop/Default/PLP-PDP card, not just the standalone
      // documentation set. Top-aligning two different-height children produces a visible ~4px
      // offset between the icon's optical centre and the name text's optical centre; `center` is
      // the robust way to align a text label against a differently-sized icon button in a
      // horizontal flex row, and matches what the design visually shows.
      alignItems: 'center',
      justifyContent: 'space-between',
      // 8px — Figma: the 24px icon column starts at x=184 inside the 208px row, and the name
      // column is 176px wide (208 - 176 - 24 = 8).
      gap: 'var(--zimm-scale-xs)',
    },

    nameLink: {
      display: 'block',
      flex: '1 1 auto',
      minWidth: 0,
      color: 'inherit',
      textDecoration: 'none',
      _focusVisible: FOCUS_VISIBLE,
    },

    bagWrapper: {
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      flexShrink: 0,
    },

    bagButton: {
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      width: 'var(--zimm-scale-600)', // 24px — Figma touchContainer, meets WCAG 2.5.8
      height: 'var(--zimm-scale-600)',
      background: 'transparent',
      border: 'none',
      padding: 0,
      color: disabled ? 'var(--zimm-color-text-muted)' : 'var(--zimm-color-text-default)',
      cursor: disabled ? 'not-allowed' : 'pointer',
      _focusVisible: FOCUS_VISIBLE,
    },

    attributesRow: {
      display: 'flex',
      alignItems: 'center',
      // 2px — confirmed via get_design_context on node 40002187:58446 (the real Wishlist
      // Card-content instance): the Attributes container's two text children have an explicit
      // `gap-[2px]` between them. Supersedes an earlier placeholder (`--zimm-scale-2xs`, 4px)
      // that was reused from zimmProductStyleCode.css.ts's label/value gap on the assumption
      // that "no horizontal offset is given" in Figma for this pair — a real value exists now.
      gap: 'var(--zimm-scale-3xs)',
      marginTop: 'var(--zimm-scale-m)', // 16px — see docblock above
    },

    colourText: {
      margin: 0,
      // Matches zimmProductStyleCode.css.ts's meta-text treatment: caption size + secondary
      // colour, deliberately quieter than the product name above it.
      textStyle: 'caption',
      color: 'var(--zimm-color-text-secondary)',
    },

    sizeText: {
      margin: 0,
      textStyle: 'caption',
      color: 'var(--zimm-color-text-secondary)',
    },

    priceWrapper: {
      marginTop: 'var(--zimm-scale-xl)', // 24px — see docblock above
      // Defensive: this is a direct flex item of root's column flex with no width property of
      // its own, so it defaults to `min-width: auto` — refusing to shrink below its content's
      // min-content size. Belt-and-braces alongside zimmProductPrice.css.ts's own flexWrap fix
      // (the actual root cause of the was/now mobile overflow), not a substitute for it.
      minWidth: 0,
    },

    // Deliberately no `display` value at all here — Figma's `hidden=true` default on this slot
    // is the Step 6 organism's hover-reveal CSS to implement on top of this component's always-
    // rendered output, not something this component's own recipe enforces (see index.tsx's
    // data-card-slot contract comment). Setting `display: 'none'` here would fight whatever the
    // organism's hover-reveal CSS tries to do.
    sizeChipWrapper: {
      marginTop: 'var(--zimm-scale-xl)', // 24px — see docblock above
    },

    notifyMeButton: {
      // 24px — matches priceWrapper/sizeChipWrapper's own marginTop above: Figma's "Content"
      // wrapper (the flex column holding name-block, price, and this notify-me link) applies a
      // uniform 24px gap between ALL direct children, confirmed via get_design_context on node
      // 40002163:41470 (Desktop, Hover, PLP/PDP, Unavailable=True). Supersedes an earlier
      // placeholder value shipped before this was confirmed.
      marginTop: 'var(--zimm-scale-xl)',
      display: 'block',
      background: 'transparent',
      border: 'none',
      padding: 0,
      textAlign: 'left',
      textStyle: 'linkSm',
      // alias/color/link/default (Figma) — not text/default, even though both resolve to the
      // same hex in this palette. Confirmed via get_design_context on node 40002163:41468, the
      // "CTA/Link" atom instance (40001908:28374/40001908:28368) this control reuses.
      color: 'var(--zimm-color-link-default)',
      cursor: 'pointer',
      _focusVisible: FOCUS_VISIBLE,
    },
  }),
};

