/*
 * SFCC-236 — real-browser proof that ZimmProductCard's image/gallery region is genuinely
 * reachable by touch, not silently intercepted by the organism's whole-card stretched-link
 * overlay ("Fix I", overrides/app/components/ui-kits/organisms/zimmProductCard/
 * zimmProductCard.css.ts). Reported live: multi-image cards rendered the slide indicator
 * correctly but a real swipe never paged the gallery — the touch gesture was landing on the
 * invisible overlay `<a>` instead of the real scroll container underneath it.
 *
 * Targets Storybook directly (http://localhost:6006 by default, override via STORYBOOK_URL), same
 * deliberate departure from this suite's usual RETAIL_APP_HOME pattern as the sibling a11y specs
 * under e2e/tests/a11y/ — see that directory's own spec for the full rationale. Lives under
 * e2e/tests/zimm/productCard/mobile/ rather than e2e/tests/a11y/mobile/ because this is a
 * functional/hit-testing concern, not an accessibility one; it still runs under the
 * `mobile-chrome` project (Pixel 5) since the reported bug is mobile-specific, even though the
 * underlying stacking bug itself is device-agnostic.
 *
 * Scope, deliberately: this does NOT attempt to simulate a full native touch-drag gesture
 * end-to-end (Playwright's `page.touchscreen` only exposes `.tap()`, not a drag/swipe primitive;
 * a hand-rolled CDP `Input.dispatchTouchEvent` sequence was considered and rejected as fragile
 * and indirect for what's actually a pure CSS stacking bug, not a gesture-recognition one). The
 * native scroll-snap mechanism itself was never broken — only which element receives the pointer
 * at a given screen position was. `document.elementFromPoint()` proves that directly and
 * precisely, which is what this file actually tests. This also does NOT attempt to observe real
 * navigation via `page.url()`: Storybook's own decorator wraps every ZimmProductCard story in a
 * `MemoryRouter` (index.stories.tsx), which deliberately never touches the real browser
 * address bar — "does the click handler call history.push with the right href" is a pure
 * React/JS question, already correctly covered by the mockable-`useHistory` Vitest test in
 * organisms/zimmProductCard/index.test.tsx. What a real browser uniquely proves, and what this
 * file focuses on instead, is real hit-testing/CSS that jsdom cannot resolve at all.
 */
const { test, expect } = require('@playwright/test');

const STORYBOOK_URL = process.env.STORYBOOK_URL || 'http://localhost:6006';
const storyUrl = (id) => `${STORYBOOK_URL}/iframe.html?id=${id}&viewMode=story`;

test.describe('ZimmProductCard media region — real hit-testing', { tag: ['@SFCC-236'] }, () => {
  test('the image/scroll region, not the stretched-link overlay, receives a hit at its own centre point', async ({
    page,
  }) => {
    await page.goto(storyUrl('commerce-zimmproductcard--multiple-images'));
    await page.waitForSelector('[data-testid="product-card"]');

    const box = await page.locator('[data-testid="card-media-scroll"]').boundingBox();
    const hit = await page.evaluate(
      ([x, y]) => {
        const el = document.elementFromPoint(x, y);
        return {
          insideScrollRegion: Boolean(el?.closest('[data-testid="card-media-scroll"]')),
          insideOverlayLink: Boolean(el?.closest('a')),
        };
      },
      [box.x + box.width / 2, box.y + box.height / 2],
    );

    expect(hit.insideScrollRegion).toBe(true);
    expect(hit.insideOverlayLink).toBe(false);
  });

  test('the media region shows a pointer cursor, confirming it is genuinely clickable, not just visually on top', async ({
    page,

