import React, { useState } from 'react';
import { describe, test, expect } from 'vitest';
import { render, screen, fireEvent } from '@testing-library/react';

/**
 * THROWAWAY AUDIT PROBE — not part of the codebase, deleted immediately after this run.
 *
 * Reproduces (verbatim mechanism, not verbatim code) liveProductCardDemoSection.tsx's
 * `DemoSizeSelectableCard` pattern:
 *   const [selectedSizeChipValue, setSelectedSizeChipValue] = useState<string | undefined>(() =>
 *     props.variation === 'plp' || props.variation === 'wishlist' ? props.selectedSizeChipValue : undefined,
 *   );
 * — a useState lazy-initializer seeded from a prop, with no effect that reconciles local
 * selection state against a later change to the sibling `sizeChipValues` prop, and a component
 * identity that the real demo keeps stable across re-renders via a hardcoded `card.id` string
 * used as the React `key` (never regenerated, so React never remounts it).
 */
type ChipValue = { value: string; label: string };

type ProbeProps = {
  seedSelectedValue: string | undefined;
  sizeChipValues: ChipValue[];
};

const ChipPickerProbe = ({ seedSelectedValue, sizeChipValues }: ProbeProps) => {
  const [selected, setSelected] = useState<string | undefined>(() => seedSelectedValue);
  return (
    <div>
      <div data-testid="selected">{selected ?? 'none'}</div>
      <div data-testid="is-selected-valid-option">{String(sizeChipValues.some((v) => v.value === selected))}</div>
      {sizeChipValues.map((chip) => (
        <button key={chip.value} type="button" onClick={() => setSelected(chip.value)}>
          {chip.label}
        </button>
      ))}
    </div>
  );
};

describe('AUDIT PROBE: useState(() => propDerived) staleness under stable identity', () => {
  test('local selection state survives a sizeChipValues prop change across a re-render, producing a selection that is no longer a valid option', () => {
    const productAChips: ChipValue[] = [
      { value: 's', label: 'Small' },
      { value: 'm', label: 'Medium' },
    ];
    const productBChips: ChipValue[] = [
      { value: 'xs', label: 'Extra Small' },
      { value: 's', label: 'Small' },
    ];

    const { rerender } = render(<ChipPickerProbe seedSelectedValue={undefined} sizeChipValues={productAChips} />);

    // Simulate a shopper picking "Medium" on the first live product this card instance shows.
    fireEvent.click(screen.getByText('Medium'));
    expect(screen.getByTestId('selected').textContent).toBe('m');

    // Simulate the underlying live product changing under the SAME component instance (e.g. a
    // background refetch of useProductSearch causing pickDemoHit to select a different hit) --
    // the real demo never remounts DemoSizeSelectableCard here, since every card's React `key`
    // is a hardcoded literal (`card.id`) that never changes across renders.
    rerender(<ChipPickerProbe seedSelectedValue={undefined} sizeChipValues={productBChips} />);

    // The mechanism under test: useState's lazy initializer runs ONLY on mount, so local
    // selection state is untouched by the prop change -- 'm' survives even though it is no
    // longer present in the new sizeChipValues list at all.
    expect(screen.getByTestId('selected').textContent).toBe('m');
    expect(screen.getByTestId('is-selected-valid-option').textContent).toBe('false');
  });
});
EOF
